'use strict';

const app = document.getElementById('app');
const icon = name => window.TicketIcons.render(name);
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money = value => new Intl.NumberFormat('vi-VN').format(Number(value) || 0) + 'đ';
const qs = values => new URLSearchParams(Object.entries(values).filter(([, v]) => v !== '' && v !== null && v !== undefined)).toString();
const state = { bootstrap: null, user: null, trip: null, selected: [], seatTab:'seats', routeVersion:0, lookup:null, search:null };
let checkoutDraft = null;
try { const value=JSON.parse(sessionStorage.getItem('ticket4t_checkout') || 'null');if(value&&typeof value==='object'&&value.tripId&&Array.isArray(value.seats)&&value.trip&&(!value.legs||Array.isArray(value.legs)&&value.legs.every(leg=>leg&&leg.tripId&&leg.trip&&Array.isArray(leg.seats))))checkoutDraft=value; } catch {}
const today = () => state.bootstrap?.today || new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const addDays = (date, days) => { const d = new Date(`${date}T12:00:00+07:00`); d.setDate(d.getDate()+days); return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(d); };
const dateLabel = (value, long = false) => { if (!value) return '—'; const date = new Date(`${String(value).slice(0,10)}T12:00:00+07:00`); return Number.isNaN(date.getTime()) ? esc(value) : new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',...(long ? {year:'numeric'} : {})}).format(date); };
const dateTimeLabel = value => value ? new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Bangkok'}).format(new Date(value)) : '—';
const duration = minutes => `${Math.floor((Number(minutes)||0)/60)} giờ${Number(minutes)%60 ? ` ${Number(minutes)%60} phút` : ''}`;
const imagePath = value => { const s = String(value || ''); return /^\/images\/[\w\-./]+$/.test(s) ? s : '/images/chuyenxe/tien-dat-1.jpg'; };
const routeHref = (from, to, date = today()) => `#/search?${qs({from,to,date})}`;
const fieldPoint = item => typeof item === 'string' ? item : item?.name || item?.address || '';
const brand = () => `<a class="brand" href="#/" aria-label="Ticket4T — Trang chủ"><img src="/app/logo.svg" width="38" height="38" alt="">Ticket4T<span class="brand-dot">.</span></a>`;
const sourceDemo = value => (value?.isDemo || value?.source === 'demo' || (!value?.source && state.bootstrap?.dataMode === 'demo'));

async function api(path, options = {}) {
  const {headers={},timeoutMs=20000,...request}=options,controller=new AbortController();
  const timeout=setTimeout(()=>controller.abort(),timeoutMs);
  try {
    const res=await fetch(path,{credentials:'same-origin',...request,headers:{'Content-Type':'application/json',...headers},signal:request.signal||controller.signal});
    let data;
    try {data=await res.json();} catch {const error=new Error('Chưa nhận đủ kết quả từ máy chủ. Vui lòng thử lại.');error.ambiguous=true;throw error;}
    if(!res.ok){const error=new Error(data.error||data.message||'Không thể xử lý yêu cầu. Vui lòng thử lại.');error.code=data.code;error.status=res.status;error.ambiguous=res.status>=500;throw error;}
    return data;
  } catch(error) {
    if(error.name==='AbortError'||error instanceof TypeError){const failure=new Error(error.name==='AbortError'?'Máy chủ phản hồi quá lâu. Vui lòng thử lại.':'Mất kết nối tới máy chủ. Vui lòng kiểm tra mạng và thử lại.');failure.ambiguous=true;throw failure;}
    throw error;
  } finally {clearTimeout(timeout);}
}

function toast(message, error = false) {
  const region = document.getElementById('toast-region');
  const el = document.createElement('div'); el.className = `toast${error ? ' error' : ''}`; el.setAttribute('role', error ? 'alert' : 'status');
  el.innerHTML = `${icon(error ? 'info' : 'check')}<span>${esc(message)}</span>`; region.append(el);
  setTimeout(() => el.remove(), 5500);
}

function navActive(route) { return (location.hash || '#/').startsWith(route) ? 'active' : ''; }
function shell(content, page = '') {
  document.title = `${page ? page + ' · ' : ''}Ticket4T · Trọn từng hành trình`;
  app.innerHTML = `<header class="site-header"><div class="container header-inner">${brand()}<nav class="main-nav" id="main-nav" aria-label="Điều hướng chính"><a class="${location.hash === '#/' || !location.hash ? 'active' : ''}" href="#/">${icon('home')}Trang chủ</a><a class="${navActive('#/search')}" href="${routeHref('ho-chi-minh','da-lat')}">${icon('bus')}Tìm chuyến xe</a><a class="${navActive('#/operators')}" href="#/operators">${icon('building')}Nhà xe</a><a class="${navActive('#/promotions')}" href="#/promotions">${icon('tag')}Ưu đãi</a><a class="${navActive('#/support')}" href="#/support">${icon('support')}Hỗ trợ</a></nav><div class="header-actions"><a class="btn btn-outline btn-small" href="#/tickets">${icon('ticket')}Vé của tôi</a><a class="login-link" href="${state.user ? '#/account' : '#/login'}">${icon('user')}<span>${esc(state.user?.fullName || 'Đăng nhập')}</span></a><button class="mobile-toggle" data-action="menu" aria-label="Mở menu" aria-expanded="false" aria-controls="main-nav">${icon('menu')}</button></div></div></header>${state.bootstrap?.dataMode === 'demo' ? '<div class="demo-bar"><strong>Dữ liệu minh họa</strong> · Lịch xe và giá vé dùng để trải nghiệm. Chưa kết nối trực tiếp với nhà xe.</div>' : ''}<main id="main">${content}</main>${footer()}`;
}
function footer() { return `<footer class="footer"><div class="container"><div class="footer-top"><div>${brand()}<p>Mỗi chuyến đi là một khởi đầu mới.<br>Chọn chỗ bạn thích, đi nơi bạn muốn.</p><div class="footer-stamp">${icon('shield')} Rõ ràng thông tin · An tâm hành trình</div></div><div><h4>Khám phá</h4><a href="${routeHref('ho-chi-minh','da-lat')}">Tìm chuyến xe</a><a href="#/operators">Danh sách nhà xe</a><a href="#/favorites">Chuyến đã lưu</a><a href="#/promotions">Ưu đãi hành trình</a><a href="#/tickets">Tra cứu vé</a><a href="#/account">Tài khoản của tôi</a></div><div><h4>Thông tin hữu ích</h4><a href="#/support">Hướng dẫn đặt vé</a><a href="#/policy?tab=cancel">Đổi và hủy vé</a><a href="#/policy?tab=terms">Điều khoản sử dụng</a><a href="#/policy?tab=privacy">Chính sách bảo mật</a></div><div><h4>Quản lý hành trình</h4><a href="#/tickets">Tra cứu bằng mã đặt chỗ</a><a href="#/support">Trung tâm hỗ trợ</a><a href="/admin">Dành cho quản trị viên</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Ticket4T. Trọn từng hành trình.</span><span>${state.bootstrap?.dataMode === 'demo' ? 'Phiên bản trải nghiệm · Dữ liệu minh họa' : 'Nền tảng đặt vé xe khách'}</span></div></div></footer>`; }
function loading(title='Đang tìm hành trình phù hợp…') { return `<div class="loading-panel" role="status"><div class="spinner"></div>${esc(title)}</div>`; }
function errorPage(message) { return `<div class="container error-page"><div class="empty-icon">${icon('info')}</div><h1>Hành trình tạm gián đoạn</h1><p>${esc(message)}</p><button class="btn" data-action="retry">${icon('refresh')}Thử lại</button> <a class="btn btn-outline" href="#/">Về trang chủ</a></div>`; }
function breadcrumb(label, previous = '') { return `<nav class="breadcrumb" aria-label="Đường dẫn"><a href="#/">Trang chủ</a>${icon('chevron')}${previous}${esc(label)}</nav>`; }
function locationOptions(selected) { return (state.bootstrap?.locations || []).map(loc => `<option value="${esc(loc.id)}" ${String(selected)===String(loc.id)?'selected':''}>${esc(loc.name)}</option>`).join(''); }
const normalizeLocation = value => String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/gi,'d').toLowerCase().replace(/[^a-z0-9]/g,'');
function locationPickerButton(id,label){return `<button class="location-picker-button" type="button" data-action="location-picker" data-target="${id}" aria-label="Tìm ${label}" aria-haspopup="dialog">${icon('search')}</button>`;}
function openLocationPicker(targetId){
  const select=document.getElementById(targetId),region=document.getElementById('modal-region');
  if(!select||region.firstElementChild)return;
  const previous=document.activeElement,title=targetId==='search-from'?'Chọn nơi xuất phát':'Chọn điểm đến';
  region.innerHTML=`<dialog id="location-dialog" class="location-dialog" aria-labelledby="location-title"><div class="location-dialog-head"><h2 id="location-title">${title}</h2><button type="button" class="location-close" aria-label="Đóng chọn địa điểm">${icon('close')}</button></div><label class="sr-only" for="location-query">Tìm tỉnh, thành phố</label><div class="location-query-field">${icon('search')}<input id="location-query" type="search" placeholder="Tìm tỉnh, thành phố…" autocomplete="off"></div><p id="location-result-count" class="muted text-small" aria-live="polite"></p><div id="location-options" class="location-options" aria-label="Các địa điểm"></div></dialog>`;
  const dialog=region.firstElementChild,input=dialog.querySelector('#location-query'),list=dialog.querySelector('#location-options');
  const aliases={'ho-chi-minh':'Sai Gon Saigon SG TPHCM HCM','sa-pa':'Sapa','buon-ma-thuot':'Dak Lak Buon Me Thuot','ha-long':'Quang Ninh'};
  const recent=storedJSON('ticket4t_locations').map(item=>item.id);
  function renderOptions(){
    const query=normalizeLocation(input.value),all=state.bootstrap.locations||[];
    const items=all.filter(loc=>normalizeLocation(`${loc.name} ${loc.id} ${aliases[loc.id]||''}`).includes(query));
    if(!query)items.sort((a,b)=>(recent.includes(a.id)?recent.indexOf(a.id):-1)<0?(recent.includes(b.id)?1:0):recent.includes(b.id)?recent.indexOf(a.id)-recent.indexOf(b.id):-1);
    dialog.querySelector('#location-result-count').textContent=query?`${items.length} địa điểm phù hợp`:'Tỉnh, thành phố · Địa điểm gần đây ở đầu danh sách';
    list.innerHTML=items.map(loc=>`<button type="button" class="location-option${select.value===loc.id?' current':''}" data-action="choose-location" data-location="${esc(loc.id)}">${icon(targetId==='search-from'?'circle-dot':'pin')}<span><strong>${esc(loc.name)}</strong><small>${esc(loc.region||'Việt Nam')}${!query&&recent.includes(loc.id)?' · Gần đây':''}</small></span>${select.value===loc.id?icon('check'):icon('chevron')}</button>`).join('')||'<p class="location-empty">Không có địa điểm phù hợp. Hãy thử tên khác.</p>';
  }
  input.addEventListener('input',renderOptions);
  input.addEventListener('keydown',event=>{if(event.key==='ArrowDown'){event.preventDefault();list.querySelector('button')?.focus();}else if(event.key==='Enter'){event.preventDefault();list.querySelector('button')?.click();}});
  list.addEventListener('keydown',event=>{if(!['ArrowDown','ArrowUp','Home','End'].includes(event.key))return;const options=[...list.querySelectorAll('button')],index=options.indexOf(document.activeElement);event.preventDefault();if(event.key==='Home')options[0]?.focus();else if(event.key==='End')options.at(-1)?.focus();else{const next=index+(event.key==='ArrowDown'?1:-1);if(next<0)input.focus();else options[Math.min(next,options.length-1)]?.focus();}});
  dialog.querySelector('.location-close').addEventListener('click',()=>dialog.close());
  list.addEventListener('click',event=>{
    const option=event.target.closest('[data-location]');if(!option||!select.isConnected)return;
    select.value=option.dataset.location;select.dispatchEvent(new Event('change',{bubbles:true}));
    try{localStorage.setItem('ticket4t_locations',JSON.stringify([{id:select.value},...storedJSON('ticket4t_locations').filter(item=>item.id!==select.value)].slice(0,6)));}catch{}
    dialog.close();
  });
  dialog.addEventListener('click',event=>{if(event.target===dialog){const bounds=dialog.getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)dialog.close();}});
  const dismissOnNavigation=()=>{if(dialog.open)dialog.close();};
  dialog.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();dialog.close();}});
  dialog.addEventListener('close',()=>{window.removeEventListener('hashchange',dismissOnNavigation);region.replaceChildren();if(previous?.isConnected)previous.focus();},{once:true});
  window.addEventListener('hashchange',dismissOnNavigation);
  renderOptions();dialog.showModal();input.focus();
}
function searchBoxV2(values={}, inline=false) { const from=values.from || 'ho-chi-minh', to=values.to || 'da-lat'; return `<form class="search-box${inline ? ' search-inline' : ''}" id="search-form"><div class="search-label">${icon('bus')}Vé xe khách<span class="badge badge-gray">Chọn chỗ trực tuyến</span></div><div class="search-fields"><div class="search-field">${icon('circle-dot')}<div class="field-inner"><label for="search-from">Nơi xuất phát</label><select id="search-from" name="from" required>${locationOptions(from)}</select></div>${locationPickerButton('search-from','nơi xuất phát')}</div><button class="swap-button" type="button" data-action="swap" aria-label="Đổi nơi xuất phát và điểm đến">${icon('swap')}</button><div class="search-field">${icon('pin')}<div class="field-inner"><label for="search-to">Điểm đến</label><select id="search-to" name="to" required>${locationOptions(to)}</select></div>${locationPickerButton('search-to','điểm đến')}</div><div class="search-field">${icon('calendar')}<div class="field-inner"><label for="search-date">Ngày khởi hành</label><input id="search-date" name="date" type="date" min="${today()}" value="${esc(values.date || today())}" required></div></div><button class="btn" type="submit">${icon('search')}Tìm chuyến xe</button></div>${!inline ? `<div class="search-hint"><span>Được yêu thích:</span><a href="${routeHref('ho-chi-minh','da-lat')}">Sài Gòn → Đà Lạt</a><span>·</span><a href="${routeHref('ha-noi','sa-pa')}">Hà Nội → Sa Pa</a><span>·</span><a href="${routeHref('ho-chi-minh','nha-trang')}">Sài Gòn → Nha Trang</a></div>` : ''}</form>`; }

function homeV2() {
  const b = state.bootstrap, routes = b.popularRoutes || [], stats=b.stats || {};
  const featured = [...routes];
  const chosen = []; const destinations = new Set();
  for (const id of ['da-lat','nha-trang','phan-thiet','vung-tau','can-tho','da-nang','sa-pa']) { const found = routes.find(r=>r.to===id); if(found&&chosen.length<4){chosen.push(found);destinations.add(found.to);} }
  for (const r of featured) if(chosen.length<4 && !destinations.has(r.to)){chosen.push(r);destinations.add(r.to);}
  shell(`<section class="hero"><div class="hero-image" role="img" aria-label="Cao nguyên Đà Lạt xanh mát"></div><div class="container"><div class="hero-eyebrow">${icon('leaf')}Cùng bạn trên mọi nẻo đường</div><h1>Đi muôn nơi.<br><em>Trọn từng hành trình.</em></h1><p class="hero-description">Từ phố quen đến miền đất mới. Tìm chuyến xe phù hợp và chọn chỗ yêu thích chỉ trong vài phút.</p><div class="hero-checks"><span>${icon('check')}Giá vé hiển thị rõ ràng</span><span>${icon('check')}Chủ động chọn chỗ</span><span>${icon('check')}Tra cứu vé dễ dàng</span></div><div class="hero-location">${icon('pin')}<div>Đà Lạt, Lâm Đồng<small>Một chút bình yên, một chuyến đi mới.</small></div></div><div class="hero-caption">VIỆT NAM · NHỮNG HÀNH TRÌNH ĐÁNG NHỚ</div></div></section><div class="container search-section">${searchBox()}<div class="trust-strip"><div class="trust-item">${icon('globe')}<div><strong>${Number(stats.locations || stats.locationCount || b.locations?.length || 0)} điểm đến</strong><span>Khám phá dọc miền đất Việt</span></div></div><div class="trust-item">${icon('bus')}<div><strong>${Number(stats.operators || stats.operatorCount || b.operators?.length || 0)} nhà xe</strong><span>${b.dataMode==='demo'?'Trong dữ liệu minh họa':'Có trong hệ thống'}</span></div></div><div class="trust-item">${icon('seat')}<div><strong>Chọn chỗ theo ý bạn</strong><span>Sơ đồ ghế trực quan</span></div></div><div class="trust-item">${icon('shield')}<div><strong>Thông tin minh bạch</strong><span>Xem giá trước khi đặt</span></div></div></div></div><section class="section popular-section"><div class="container"><div class="section-head"><div><div class="eyebrow">Lên xe, đi thôi</div><h2>Điểm đến đang gọi bạn</h2><p>Biển xanh, phố núi hay thành phố nhộn nhịp — bạn chọn nơi nào?</p></div><a class="text-link" href="${routeHref('ho-chi-minh','da-lat')}">Khám phá chuyến xe ${icon('arrow')}</a></div>${chosen.length ? `<div class="destination-grid">${chosen.map(r=>destinationCard(r)).join('')}</div>` : '<div class="card empty"><h3>Những hành trình mới đang được chuẩn bị</h3><p>Lịch xe sẽ xuất hiện khi nhà xe cập nhật chuyến và giá vé.</p></div>'}<div class="benefits"><div class="benefit-card"><div class="benefit-icon">${icon('wallet')}</div><div><h3>Biết rõ giá, chọn dễ dàng</h3><p>So sánh chuyến xe và giá từng chỗ trước khi đặt. Tổng tiền luôn hiển thị rõ ràng.</p></div></div><div class="benefit-card"><div class="benefit-icon">${icon('seat')}</div><div><h3>Một chỗ ngồi, đúng ý bạn</h3><p>Giường nằm, limousine hay cabin riêng — tìm lựa chọn cho hành trình của mình.</p></div></div><div class="benefit-card"><div class="benefit-icon">${icon('ticket')}</div><div><h3>Vé luôn trong tầm tay</h3><p>Tra cứu mã đặt chỗ, xem thông tin chuyến và quản lý vé ngay trên nền tảng.</p></div></div></div></div></section><section class="section route-section"><div class="container"><div class="section-head"><div><div class="eyebrow">Những hành trình quen thuộc</div><h2>Tuyến đường phổ biến</h2><p>Chọn tuyến, chọn ngày và bắt đầu hành trình.</p></div><span class="badge badge-gray">${b.dataMode==='demo'?'Giá tham khảo từ dữ liệu minh họa':'Giá thấp nhất hiện có'}</span></div><div class="route-grid">${routes.slice(0,9).map(r=>`<a class="route-link" href="${routeHref(r.from,r.to)}"><div><h4>${esc(r.fromName)} ${icon('arrow')} ${esc(r.toName)}</h4><p>${duration(r.durationMinutes)} · Chọn chỗ trực tuyến</p></div><div class="route-price"><small>Chỉ từ</small>${money(r.minPrice)}</div></a>`).join('') || '<p class="muted">Chưa có tuyến đường được mở bán.</p>'}</div></div></section><section class="section"><div class="container"><div class="section-head"><div><div class="eyebrow">Đồng hành cùng bạn</div><h2>Gặp những nhà xe</h2><p>Xem tiện ích, chính sách và lịch xe trước khi lựa chọn.</p></div><a class="text-link" href="#/operators">Tất cả nhà xe ${icon('arrow')}</a></div><div class="operator-preview">${(b.operators || []).slice(0,4).map(o=>`<a class="card operator-mini" href="#/operators/${encodeURIComponent(o.id)}"><div class="operator-mark">${esc(initials(o.name))}</div><div><h3>${esc(o.name)}</h3>${ratingHtml(o)}</div></a>`).join('')}</div></div></section><div class="container"><section class="journey-banner"><div><div class="eyebrow">Sẵn sàng cho chuyến đi tiếp theo?</div><h2>Đặt một chuyến xe.<br>Mở một hành trình mới.</h2><p>Mọi thông tin bạn cần, từ lúc chọn chỗ đến khi lên xe.</p></div><a class="btn btn-light" href="#/support">Xem hướng dẫn đặt vé ${icon('arrow')}</a></section></div>`);
}
function initials(name) { return String(name || 'NX').replace(/\([^)]*\)/g,'').trim().split(' ').filter(Boolean).slice(-2).map(w=>w[0]).join('').toUpperCase(); }
function ratingHtml(o) { return Number(o.rating)>0 ? `<div class="rating">${icon('star')}${Number(o.rating).toFixed(1)}<span>${sourceDemo(o)?'· Điểm minh họa':`(${Number(o.reviewCount)||0} đánh giá)`}</span></div>` : '<span class="muted text-small">Chưa có đánh giá</span>'; }
function destinationCard(r) { return `<a class="destination-card" href="${routeHref(r.from,r.to)}"><div class="destination-photo"><img src="${esc(imagePath(r.image))}" alt="${esc(r.toName)}" loading="lazy"><span class="photo-tag">${['da-lat','sa-pa','lam-dong'].includes(r.to)?'Hẹn với phố núi':['nha-trang','da-nang','vung-tau','phan-thiet'].includes(r.to)?'Biển đang đợi bạn':'Khám phá Việt Nam'}</span><h3>${esc(r.toName)}</h3></div><div class="destination-content"><div class="route-name">Từ ${esc(r.fromName)} · ${duration(r.durationMinutes)}</div><div class="destination-bottom"><div><p>Giá vé từ</p><strong>${money(r.minPrice)}</strong></div><span class="circle-arrow">${icon('arrow')}</span></div></div></a>`; }

function readSearchV2() { const q=new URLSearchParams(location.hash.split('?')[1] || ''); return {from:q.get('from') || 'ho-chi-minh',to:q.get('to') || 'da-lat',date:q.get('date') || today(),operator:q.get('operator')||'',type:q.get('type')||'',minPrice:q.get('minPrice')||'',maxPrice:q.get('maxPrice')||'',time:q.get('time')||'',sort:q.get('sort')||'departure',page:Number(q.get('page'))||1,limit:8}; }
function locName(id) { return state.bootstrap?.locations?.find(loc=>String(loc.id)===String(id))?.name || id; }
async function searchPageV2(version) {
  const params=readSearch(); state.search=params;
  const title=`${locName(params.from)} đến ${locName(params.to)}`;
  shell(`<div class="container page-main">${breadcrumb('Tìm chuyến xe')}${searchBox(params,true)}<div class="page-heading"><div class="eyebrow">Chọn một chuyến đi phù hợp</div><h1>${esc(locName(params.from))} ${icon('arrow')} ${esc(locName(params.to))}</h1><p>Ngày ${dateLabel(params.date,true)} · Giá hiển thị theo từng chỗ</p></div><div class="date-tabs">${[-1,0,1,2,3].map(n=>{const d=addDays(params.date,n); if(d<today())return ''; const day=new Intl.DateTimeFormat('vi-VN',{weekday:'short'}).format(new Date(`${d}T12:00:00+07:00`));return `<button class="date-tab${n===0?' active':''}" data-action="change-date" data-date="${d}"><strong>${dateLabel(d)}</strong>${d===today()?'Hôm nay':day}</button>`;}).join('')}</div><div class="results-layout"><aside><button class="btn btn-outline btn-small mobile-filters" data-action="filters">${icon('filter')}Bộ lọc chuyến xe</button>${filterPanel(params)}<p class="filter-note">${state.bootstrap.dataMode==='demo'?'Lịch xe và đánh giá đang dùng dữ liệu minh họa.':'Thông tin được cập nhật từ lịch xe trong hệ thống.'}</p></aside><section id="search-results" aria-live="polite">${loading()}</section></div></div>`,title);
  try { const data=await api(`/api/trips?${qs(params)}`); if(version!==state.routeVersion)return; document.getElementById('search-results').innerHTML=searchResults(data,params); }
  catch(e){if(version!==state.routeVersion)return; document.getElementById('search-results').innerHTML=`<div class="card empty"><h3>Chưa thể tải lịch xe</h3><p>${esc(e.message)}</p><button class="btn" data-action="retry">Thử lại</button></div>`;}
}
function filterPanelV2(p) { return `<form class="filter-panel" id="filter-form"><div class="filter-title">${icon('filter')}Bộ lọc<button class="text-link" type="button" data-action="clear-filters">Đặt lại</button></div><div class="filter-group"><h4>Giờ khởi hành</h4>${[['','Tất cả thời gian'],['morning','Sáng · 06:00 – 12:00'],['afternoon','Chiều · 12:00 – 18:00'],['evening','Tối · 18:00 – 24:00'],['night','Đêm · 00:00 – 06:00']].map(([v,n])=>`<label><input type="radio" name="time" value="${v}" ${p.time===v?'checked':''}>${n}</label>`).join('')}</div><div class="filter-group"><h4>Loại xe</h4><label><input type="radio" name="type" value="" ${!p.type?'checked':''}>Tất cả loại xe</label>${(state.bootstrap.busTypes||[]).map(t=>`<label><input type="radio" name="type" value="${esc(t.id)}" ${p.type===t.id?'checked':''}>${esc(t.name)}</label>`).join('')}</div><div class="filter-group"><h4>Nhà xe</h4><label><input type="radio" name="operator" value="" ${!p.operator?'checked':''}>Tất cả nhà xe</label>${(state.bootstrap.operators||[]).map(o=>`<label><input type="radio" name="operator" value="${esc(o.id)}" ${p.operator===o.id?'checked':''}>${esc(o.name)}</label>`).join('')}</div><div class="filter-group"><h4>Khoảng giá (VNĐ / chỗ)</h4><label class="sr-only" for="filter-min">Giá thấp nhất</label><input type="number" id="filter-min" name="minPrice" min="0" step="10000" placeholder="Giá thấp nhất" value="${esc(p.minPrice)}"><label class="sr-only" for="filter-max">Giá cao nhất</label><input type="number" id="filter-max" name="maxPrice" min="0" step="10000" placeholder="Giá cao nhất" value="${esc(p.maxPrice)}"><button class="btn btn-block btn-small" type="submit">Áp dụng bộ lọc</button></div></form>`; }
function searchResults(data,p) { return `<div class="results-toolbar"><div><strong>${Number(data.total)||0} chuyến xe</strong> <span class="muted">phù hợp hành trình</span></div><label class="flex muted">Sắp xếp<select id="sort-select" class="sort-select" aria-label="Sắp xếp chuyến xe"><option value="departure" ${p.sort==='departure'?'selected':''}>Khởi hành sớm nhất</option><option value="price" ${p.sort==='price'?'selected':''}>Giá thấp nhất</option><option value="rating" ${p.sort==='rating'?'selected':''}>Đánh giá cao nhất</option></select></label></div>${data.trips?.length ? `<div class="trip-list">${data.trips.map(tripCard).join('')}</div>${pagination(data)}` : `<div class="card empty"><div class="empty-icon">${icon('bus')}</div><h3>Chưa có chuyến xe phù hợp</h3><p>Hãy đổi ngày, chọn tuyến khác hoặc nới bộ lọc để tìm thêm lựa chọn.</p><button class="btn" data-action="clear-filters">Xóa bộ lọc</button> <a class="btn btn-outline" href="#/">Đổi hành trình</a></div>`}`; }
function tripCardV2(t) { return `<article class="trip-card"><a class="trip-photo" href="#/trip/${encodeURIComponent(t.id)}" aria-label="Xem xe ${esc(t.operatorName)}"><img src="${esc(imagePath(t.image))}" alt="Xe ${esc(t.operatorName)}" loading="lazy"></a><div><div class="trip-card-header"><h3><a href="#/operators/${encodeURIComponent(t.operatorId)}">${esc(t.operatorName)}</a></h3>${ratingHtml(t)}</div><div class="trip-type">${icon(/cabin/i.test(t.typeName||t.type)?'cabin':/giường/i.test(t.typeName||t.type)?'bed':'bus')}${esc(t.typeName || t.type)} · ${Number(t.totalSeats)||0} chỗ</div>${timeHtml(t)}<div class="trip-features">${amenitiesHtml(t.amenities,3)}</div>${sourceDemo(t)?'<span class="trip-data-tag">Lịch xe minh họa</span>':''}</div><div class="trip-card-price"><span class="price-caption">Giá vé từ</span><strong>${money(t.price)}</strong><span class="seats-caption">Còn ${Number(t.availableSeats)||0} chỗ trống</span><a class="btn" href="#/trip/${encodeURIComponent(t.id)}">Chọn chuyến ${icon('arrow')}</a></div></article>`; }
function timeHtml(t) { return `<div class="trip-times"><div class="trip-time"><strong>${esc(t.departureTime)}</strong><span>${esc(t.fromName)}</span></div><div class="time-line">${duration(t.durationMinutes)}</div><div class="trip-time"><strong>${esc(t.arrivalTime)}</strong><span>${esc(t.toName)}${t.arrivalDate && t.arrivalDate!==t.date?' (+1 ngày)':''}</span></div></div>`; }
function amenitiesHtml(items,limit=20) { const values=Array.isArray(items)?items:['Điều hòa']; return values.slice(0,limit).map(item=>{const name=typeof item==='string'?item:item.name||item.label||'';const lower=name.toLowerCase();const ic=lower.includes('wifi')||lower.includes('wi-fi')?'wifi':lower.includes('nước')?'bottle':lower.includes('usb')?'usb':lower.includes('sạc')?'bolt':lower.includes('điều hòa')||lower.includes('máy lạnh')?'snowflake':lower.includes('cabin')||lower.includes('phòng')?'cabin':lower.includes('giường')?'bed':lower.includes('ghế')?'seat':lower.includes('hành lý')?'luggage':lower.includes('khuyết tật')?'accessible':'check';return `<span>${icon(ic)}${esc(name)}</span>`;}).join(''); }
function pagination(data) { if(Number(data.pages)<2)return ''; return `<nav class="pagination" aria-label="Phân trang">${Number(data.page)>1?`<button data-action="page" data-page="${Number(data.page)-1}" aria-label="Trang trước">←</button>`:''}${Array.from({length:Number(data.pages)},(_,i)=>i+1).filter(n=>n===1||n===Number(data.pages)||Math.abs(n-Number(data.page))<=2).map(n=>`<button data-action="page" data-page="${n}" class="${n===Number(data.page)?'active':''}" ${n===Number(data.page)?'aria-current="page"':''}>${n}</button>`).join('')}${Number(data.page)<Number(data.pages)?`<button data-action="page" data-page="${Number(data.page)+1}" aria-label="Trang sau">→</button>`:''}</nav>`; }

async function tripPageV2(id,version) {
  shell(`<div class="container page-main">${breadcrumb('Chi tiết chuyến xe')}${loading('Đang kiểm tra chỗ trống…')}</div>`,'Chi tiết chuyến xe');
  try { const data=await api(`/api/trips/${encodeURIComponent(id)}`); if(version!==state.routeVersion)return; const t=data.trip||data; if(state.trip?.id!==t.id)state.selected=[];state.trip=t;state.selected=state.selected.filter(label=>t.seats?.some(s=>s.label===label&&isSelectable(s)));state.seatTab='seats';renderTrip(); }
  catch(e){if(version===state.routeVersion)shell(errorPage(e.message),'Chi tiết chuyến xe');}
}
function renderTripV2() {
  const t=state.trip; const before=`<a href="${routeHref(t.from,t.to,t.date)}">${esc(t.fromName)} → ${esc(t.toName)}</a>${icon('chevron')}`;
  shell(`<div class="container page-main">${breadcrumb('Chọn chỗ',before)}<div class="detail-heading"><div><div class="eyebrow">Một chỗ cho hành trình của bạn</div><h1>${esc(t.fromName)} ${icon('arrow')} ${esc(t.toName)}</h1><p>${dateLabel(t.date,true)} · ${esc(t.departureTime)} · ${duration(t.durationMinutes)}</p></div>${sourceDemo(t)?'<span class="badge badge-warm">Chuyến xe minh họa</span>':'<span class="badge">Lịch xe trong hệ thống</span>'}</div><div class="detail-layout"><div><article class="card detail-hero"><img src="${esc(imagePath(t.image))}" alt="Xe ${esc(t.operatorName)}"><div><h2>${esc(t.operatorName)}</h2><div class="flex wrap">${ratingHtml(t)}<span class="badge badge-gray">${esc(t.typeName||t.type)}</span></div>${timeHtml(t)}<div class="trip-features">${amenitiesHtml(t.amenities)}</div></div></article><section class="card"><div class="tabs" role="tablist" aria-label="Thông tin chuyến xe"><button class="tab-button ${state.seatTab==='seats'?'active':''}" data-action="trip-tab" data-tab="seats" role="tab" aria-selected="${state.seatTab==='seats'}">${icon('seat')}Chọn chỗ</button><button class="tab-button ${state.seatTab==='info'?'active':''}" data-action="trip-tab" data-tab="info" role="tab" aria-selected="${state.seatTab==='info'}">${icon('info')}Thông tin chuyến</button><button class="tab-button ${state.seatTab==='reviews'?'active':''}" data-action="trip-tab" data-tab="reviews" role="tab" aria-selected="${state.seatTab==='reviews'}">${icon('star')}Đánh giá</button></div><div class="tab-content" id="trip-tab-content" role="tabpanel">${tripTabContent()}</div></section></div><aside id="seat-summary">${seatSummary()}</aside></div></div>`,'Chọn chỗ · '+t.operatorName);
}
function tripTabContentV2() { const t=state.trip; if(state.seatTab==='info')return `<h3 class="info-title">Điểm đón và trả khách</h3><div class="notice">${icon('info')}<span>Chọn điểm đón, trả cụ thể ở bước tiếp theo. Thời gian dự kiến có thể thay đổi theo điều kiện giao thông.</span></div><div class="info-grid"><div><h4 class="info-title">Điểm đón</h4><ul class="point-list">${(t.pickupPoints||[]).map(p=>`<li>${icon('pin')}${esc(fieldPoint(p))}</li>`).join('')}</ul></div><div><h4 class="info-title">Điểm trả</h4><ul class="point-list">${(t.dropoffPoints||[]).map(p=>`<li>${icon('pin')}${esc(fieldPoint(p))}</li>`).join('')}</ul></div></div><h3 class="info-title">Chính sách chuyến xe</h3><ul class="policy-list">${policies(t).map(p=>`<li>${esc(p)}</li>`).join('')}</ul><a class="text-link text-small" href="#/policy?tab=cancel">Xem hướng dẫn đổi và hủy vé ${icon('arrow')}</a>`;
  if(state.seatTab==='reviews')return `<div id="trip-reviews">${loading('Đang tải đánh giá…')}</div>`;
  const seats=t.seats||[], decks=[...new Set(seats.map(s=>s.deck||1))];return `<div class="seat-head"><div><h3>Chọn chỗ yêu thích</h3><p>Giá có thể khác nhau theo vị trí. Chọn tối đa 6 chỗ mỗi lần đặt.</p></div><button class="text-link" data-action="refresh-seats">${icon('refresh')}Cập nhật</button></div><div class="seat-legend"><span><i class="seat-dot"></i>Còn trống</span><span><i class="seat-dot selected"></i>Đang chọn</span><span><i class="seat-dot booked"></i>Đã đặt</span><span><i class="seat-dot held"></i>Đang giữ</span></div><div class="seat-decks">${decks.map(deck=>`<div class="seat-deck"><h4>${decks.length>1?`Tầng ${esc(deck)}`:'Sơ đồ chỗ ngồi'}</h4><div class="bus-frame"><div class="bus-front">${icon('wheel')}Đầu xe</div><div class="seat-grid">${seats.filter(s=>(s.deck||1)===deck).map(s=>`<button class="seat ${s.status}${state.selected.includes(s.label)?' selected':''}" data-action="seat" data-label="${esc(s.label)}" ${!isSelectable(s)||t.bookingOpen===false?'disabled':''} aria-label="Chỗ ${esc(s.label)}, ${money(s.price)}, ${isSelectable(s)?'còn trống':s.status==='held'?'đang giữ':'đã đặt'}" aria-pressed="${state.selected.includes(s.label)}" title="${money(s.price)}">${esc(s.label)}</button>`).join('')}</div></div></div>`).join('')}</div><p class="seat-limit">Sơ đồ mô tả vị trí chỗ ngồi. ${sourceDemo(t)?'Chỗ trống được quản lý trong dữ liệu minh họa.':'Chỗ được xác nhận khi hoàn tất đặt vé.'}</p>`; }
function policies(t) { const p=t.policies;if(Array.isArray(p))return p.map(v=>typeof v==='string'?v:v.text||v.name||'');if(p && typeof p==='object')return Object.values(p).filter(v=>typeof v==='string');return ['Có mặt tại điểm đón trước giờ khởi hành ít nhất 30 phút.','Giữ mã đặt chỗ và số điện thoại để đối chiếu khi lên xe.','Việc hủy vé tuân theo điều kiện của chuyến và trạng thái thanh toán.']; }
function selectedTotal() { return (state.trip?.seats||[]).filter(s=>state.selected.includes(s.label)).reduce((sum,s)=>sum+Number(s.price||state.trip.price),0); }
function seatSummaryV2() { const t=state.trip;return `<div class="card summary-card"><h3>Hành trình của bạn</h3><div class="summary-line"><span>Nhà xe</span><strong>${esc(t.operatorName)}</strong></div><div class="summary-line"><span>Khởi hành</span><strong>${esc(t.departureTime)} · ${dateLabel(t.date,true)}</strong></div><div class="summary-line"><span>Tuyến đường</span><strong>${esc(t.fromName)} → ${esc(t.toName)}</strong></div><hr class="divider"><div class="summary-line"><span>Chỗ đã chọn</span><div class="selected-chips">${state.selected.length?state.selected.map(s=>`<span class="selected-chip">${esc(s)}</span>`).join(''):'<span class="muted text-small">Chưa chọn chỗ</span>'}</div></div><div class="summary-line"><span>Số lượng</span><strong>${state.selected.length} chỗ</strong></div><div class="summary-total"><span>Tổng tiền</span><strong>${money(selectedTotal())}</strong></div><button class="btn btn-block" data-action="checkout" ${!state.selected.length?'disabled':''}>Tiếp tục đặt vé ${icon('arrow')}</button><p class="summary-note">${state.selected.length?'Chỗ bạn chọn sẽ được kiểm tra lại khi đặt.':'Chọn chỗ trên sơ đồ để xem tổng tiền.'}<br>${sourceDemo(t)?'Đây là đặt chỗ trải nghiệm, chưa phải vé của nhà xe.':'Thông tin đặt chỗ cần được nhà xe xác nhận.'}</p></div>`; }

async function loadReviews(operatorId, elementId='trip-reviews') { const el=document.getElementById(elementId);if(!el)return;const version=state.routeVersion;try{const data=await api(`/api/operators/${encodeURIComponent(operatorId)}`);if(!document.getElementById(elementId)||version!==state.routeVersion)return;document.getElementById(elementId).innerHTML=reviewsHtml(data.reviews||[]);}catch(e){if(document.getElementById(elementId)&&version===state.routeVersion)document.getElementById(elementId).innerHTML=`<div class="empty"><h3>Chưa có đánh giá để hiển thị</h3><p>${esc(e.status===404?'Đánh giá sẽ xuất hiện khi khách hoàn tất chuyến đi.':e.message)}</p></div>`;} }
function reviewsHtml(reviews) { return reviews.length?`${state.bootstrap.dataMode==='demo'?'<div class="notice notice-warm" style="margin-bottom:20px">'+icon('info')+'<span>Các đánh giá bên dưới là dữ liệu minh họa, không phải nhận xét đã được xác thực từ khách hàng.</span></div>':''}${reviews.map(r=>`<article class="review-card"><div class="flex between"><h4>${esc(r.authorName||r.fullName||r.author||r.name||'Khách hàng')}</h4><div class="rating">${icon('star')}${Number(r.rating)||0}/5</div></div><time>${dateTimeLabel(r.createdAt||r.date)}</time><p>${esc(r.comment||r.content||r.text)}</p></article>`).join('')}`:'<div class="empty"><div class="empty-icon">'+icon('star')+'</div><h3>Hành trình mới, đang chờ đánh giá</h3><p>Đánh giá sẽ được hiển thị khi khách hoàn tất chuyến đi.</p></div>'; }

function saveDraft() { checkoutDraft={tripId:state.trip.id,seats:[...state.selected],trip:state.trip};sessionStorage.setItem('ticket4t_checkout',JSON.stringify(checkoutDraft)); }
async function checkoutPageV2(version) {
  if(!checkoutDraft?.tripId || !checkoutDraft.seats?.length){shell(`<div class="container page-main"><div class="card empty"><div class="empty-icon">${icon('seat')}</div><h3>Chọn chuyến và chỗ trước nhé</h3><p>Hành trình của bạn bắt đầu từ một chuyến xe phù hợp.</p><a class="btn" href="${routeHref('ho-chi-minh','da-lat')}">Tìm chuyến xe</a></div></div>`,'Đặt vé');return;}
  shell(`<div class="container page-main">${loading('Đang kiểm tra thông tin chuyến xe…')}</div>`,'Đặt vé');
  try{const data=await api(`/api/trips/${encodeURIComponent(checkoutDraft.tripId)}`);if(version!==state.routeVersion)return;const t=data.trip||data;state.trip=t;state.selected=checkoutDraft.seats;const unavailable=state.selected.filter(label=>!t.seats?.some(s=>s.label===label&&isSelectable(s)));if(unavailable.length){state.selected=state.selected.filter(s=>!unavailable.includes(s));toast(`Chỗ ${unavailable.join(', ')} vừa được đặt. Vui lòng chọn lại.`,true);location.hash=`#/trip/${encodeURIComponent(t.id)}`;return;}renderCheckout();}
  catch(e){if(version===state.routeVersion)shell(errorPage(e.message),'Đặt vé');}
}
const onlinePaymentMethods=['vnpay','momo','zalopay'];
const paymentMethodName=method=>({cash:'Tại nhà xe',vnpay:'VNPAY',momo:'MoMo',zalopay:'ZaloPay'}[method]||method);
function checkoutPaymentOptions(trip,methods){
  const enabled=sourceDemo(trip)?[]:methods.filter(method=>method.enabled&&onlinePaymentMethods.includes(method.id));
  return `<label class="payment-option"><input type="radio" name="paymentMethod" value="cash" checked><div><strong>Thanh toán tại nhà xe</strong><p>Tạo mã giữ chỗ. Chưa ghi nhận thanh toán.</p></div>${icon('cash')}</label>${enabled.map(method=>`<label class="payment-option"><input type="radio" name="paymentMethod" value="${esc(method.id)}"><div><strong>Thanh toán qua ${esc(paymentMethodName(method.id))}</strong><p>Chuyển sang cổng thanh toán để hoàn tất giao dịch.</p></div>${icon(method.id==='vnpay'?'qr':'wallet')}</label>`).join('')}${!enabled.length?`<div class="notice notice-warm">${icon('info')}<span>${sourceDemo(trip)?'Chuyến minh họa chỉ tạo đặt chỗ trải nghiệm, không thanh toán qua cổng trực tuyến.':'Thanh toán trực tuyến chưa được mở. Hiện bạn có thể tạo đặt chỗ và chọn thanh toán tại nhà xe.'}</span></div>`:''}`;
}
function renderCheckoutV2() { const t=state.trip, user=state.user||{}, payments=state.bootstrap.paymentMethods||[{id:'cash',enabled:true}];shell(`<div class="container page-main">${breadcrumb('Thông tin đặt vé',`<a href="#/trip/${encodeURIComponent(t.id)}">Chọn chỗ</a>${icon('chevron')}`)}<div class="checkout-steps"><span>${icon('check')}Chọn chỗ</span><i></i><span class="active"><b class="step-number">2</b>Thông tin & thanh toán</span><i></i><span><b class="step-number">3</b>Thông tin đặt chỗ</span></div><div class="detail-layout"><form id="checkout-form" class="stack"><section class="card pad form-section"><h2>Thông tin hành khách</h2><p>Mã đặt chỗ gắn với số điện thoại của bạn. Vui lòng điền thông tin chính xác.</p><div id="checkout-error" class="form-error" role="alert"></div>${!state.user?'<div class="notice" style="margin-bottom:22px">'+icon('user')+'<span>Bạn có thể đặt vé ngay. <a class="text-link" href="#/login?next=checkout">Đăng nhập</a> để lưu hành trình trong tài khoản.</span></div>':''}<div class="form-grid"><div class="form-field full"><label for="fullName">Họ và tên *</label><input id="fullName" name="fullName" autocomplete="name" value="${esc(user.fullName)}" placeholder="Nguyễn Văn An" minlength="2" maxlength="100" required></div><div class="form-field"><label for="phone">Số điện thoại *</label><input id="phone" name="phone" type="tel" autocomplete="tel" value="${esc(user.phone)}" placeholder="0901 234 567" pattern="[0-9+ ]{9,20}" required></div><div class="form-field"><label for="email">Email nhận thông tin *</label><input id="email" name="email" type="email" autocomplete="email" value="${esc(user.email)}" placeholder="ban@email.com" maxlength="254" required></div></div></section><section class="card pad form-section"><h2>Điểm đón và trả khách</h2><p>Có mặt tại điểm đón ít nhất 30 phút trước giờ khởi hành.</p><div class="form-grid"><div class="form-field"><label for="pickup">Điểm đón *</label><select name="pickup" id="pickup" required>${(t.pickupPoints||[]).map(p=>`<option value="${esc(fieldPoint(p))}">${esc(fieldPoint(p))}</option>`).join('')}</select></div><div class="form-field"><label for="dropoff">Điểm trả *</label><select name="dropoff" id="dropoff" required>${(t.dropoffPoints||[]).map(p=>`<option value="${esc(fieldPoint(p))}">${esc(fieldPoint(p))}</option>`).join('')}</select></div></div></section><section class="card pad form-section"><h2>Phương thức thanh toán</h2><p>Trạng thái thanh toán sẽ được hiển thị trên thông tin đặt chỗ.</p><div class="payment-options">${checkoutPaymentOptions(t,payments)}</div>${sourceDemo(t)?'<div class="notice notice-warm" style="margin-top:20px">'+icon('info')+'<span><strong>Đặt chỗ trải nghiệm.</strong> Chuyến xe này là dữ liệu minh họa. Mã đặt chỗ không dùng để lên xe hoặc thanh toán cho nhà xe.</span></div>':''}<label class="consent"><input type="checkbox" name="consent" required><span>Tôi đã kiểm tra hành trình và đồng ý với <a href="#/policy?tab=terms" target="_blank" rel="noopener">điều khoản sử dụng</a>, <a href="#/policy?tab=cancel" target="_blank" rel="noopener">chính sách hủy vé</a>${sourceDemo(t)?' và hiểu đây là đặt chỗ minh họa':''}.</span></label></section><button type="submit" class="btn btn-block" id="book-button">${sourceDemo(t)?'Tạo đặt chỗ trải nghiệm':'Xác nhận đặt chỗ'} ${icon('arrow')}</button></form><aside><div class="card summary-card"><h3>Kiểm tra hành trình</h3><div class="summary-line"><span>Tuyến xe</span><strong>${esc(t.fromName)} → ${esc(t.toName)}</strong></div><div class="summary-line"><span>Nhà xe</span><strong>${esc(t.operatorName)}</strong></div><div class="summary-line"><span>Loại xe</span><strong>${esc(t.typeName||t.type)}</strong></div><div class="summary-line"><span>Ngày đi</span><strong>${dateLabel(t.date,true)}</strong></div><div class="summary-line"><span>Giờ đi</span><strong>${esc(t.departureTime)}</strong></div><hr class="divider"><div class="summary-line"><span>Chỗ đã chọn</span><strong>${state.selected.map(esc).join(', ')}</strong></div><div class="summary-line"><span>Giá từng chỗ</span><strong>${(t.seats||[]).filter(s=>state.selected.includes(s.label)).map(s=>`${esc(s.label)} · ${money(s.price)}`).join('<br>')}</strong></div><div class="summary-total"><span>Tổng thanh toán</span><strong>${money(selectedTotal())}</strong></div><a class="text-link text-small" href="#/trip/${encodeURIComponent(t.id)}">${icon('seat')}Thay đổi chỗ</a><p class="summary-note">${sourceDemo(t)?'Tổng tiền minh họa. Chưa phát sinh giao dịch thực tế.':'Vui lòng kiểm tra lại ngày và giờ khởi hành.'}</p></div></aside></div></div>`,'Thông tin đặt vé'); }

const statuses={reserved:['Đang giữ chỗ','badge-warm'],pending_payment:['Chờ thanh toán','badge-warm'],confirmed:['Đã xác nhận',''],cancelled:['Đã hủy','badge-danger'],expired:['Đã hết hạn','badge-gray'],refund_pending:['Chờ hoàn tiền','badge-warm']};
function statusBadge(b) { const s=b.paymentStatus==='refunded'?['Đã hủy · Đã hoàn tiền','badge-gray']:b.paymentStatus==='refund_pending'?['Đang chờ hoàn tiền','badge-warm']:statuses[b.status]||[b.status||'Đang xử lý','badge-gray'];return `<span class="badge ${s[1]}">${esc(s[0])}</span>`; }
function receiptCopy(b) {
  const paymentLabels={pending:'Chưa thanh toán',paid:'Đã thanh toán',refund_pending:'Chờ hoàn tiền',refunded:'Đã hoàn tiền'};
  const copy={paymentLabel:paymentLabels[b.paymentStatus]||'Đang xử lý',title:'Thông tin đặt chỗ của bạn',description:'Thanh toán theo xác nhận của nhà xe.',notice:'Đặt chỗ chưa ghi nhận thanh toán. Vui lòng thanh toán theo xác nhận của nhà xe.'};
  if(b.expiresAt){copy.description='Đặt chỗ chưa ghi nhận thanh toán. Vui lòng hoàn tất trước thời hạn giữ chỗ.';copy.notice='Mã đặt chỗ giữ các chỗ đã chọn đến thời hạn hiển thị. Nếu chưa thanh toán khi hết hạn, đặt chỗ được giải phóng tự động.';}
  if(b.paymentStatus==='paid'){copy.title='Thanh toán đã được ghi nhận';copy.description='Lưu mã đặt chỗ để đối chiếu khi lên xe.';copy.notice='Có mặt tại điểm đón trước giờ khởi hành 30 phút và mang theo mã đặt chỗ cùng số điện thoại đã đăng ký.';}
  if(b.status==='cancelled'||b.status==='expired'){copy.title=b.status==='expired'?'Đặt chỗ đã hết hạn':'Đặt chỗ đã được hủy';copy.description='Các chỗ đã được giải phóng. Đặt chỗ này không còn hiệu lực.';copy.notice='Đặt chỗ này không dùng để lên xe. Vui lòng tìm chuyến và tạo đặt chỗ mới nếu bạn muốn tiếp tục hành trình.';}
  if(b.paymentStatus==='refund_pending'){copy.title='Đang chờ hoàn tiền';copy.description='Yêu cầu hoàn tiền đang được xử lý. Chưa ghi nhận tiền đã hoàn.';copy.notice='Đặt chỗ này không dùng để lên xe. Khoản thanh toán đang chờ hoàn; trạng thái sẽ cập nhật khi có xác nhận hoàn tiền.';}
  if(b.paymentStatus==='refunded'){copy.title='Đã hoàn tiền';copy.description='Khoản hoàn tiền đã được ghi nhận. Đặt chỗ đã hủy và không còn hiệu lực.';copy.notice='Đặt chỗ này không dùng để lên xe. Khoản hoàn tiền đã được xác nhận; bạn có thể tạo hành trình mới khi cần.';}
  if(sourceDemo(b)){copy.title='Đặt chỗ trải nghiệm của bạn';copy.description='Đây là thông tin minh họa, không dùng để lên xe.';copy.notice='Hệ thống đang sử dụng dữ liệu minh họa. Đặt chỗ này không được gửi đến nhà xe và không phải vé vận chuyển.';}
  return copy;
}
async function bookingPage(code,version) {
  const p=new URLSearchParams(location.hash.split('?')[1]||''),phone=p.get('phone') || (state.lookup?.code===code?state.lookup.phone:'') || paymentContact(code);
  shell(`<div class="container page-main">${loading('Đang tải thông tin đặt chỗ…')}</div>`,'Thông tin đặt chỗ');
  try{const data=await api(`/api/bookings/lookup?${qs({code,phone})}`);if(version!==state.routeVersion)return;state.lookup=data.booking;renderReceipt(data.booking);attachReviewForm(data.booking);}
  catch(e){if(version===state.routeVersion)shell(`<div class="container page-main"><div class="card empty"><div class="empty-icon">${icon('ticket')}</div><h3>Chưa tìm thấy thông tin đặt chỗ</h3><p>${esc(e.message)}</p><a class="btn" href="#/tickets">Tra cứu bằng mã và số điện thoại</a></div></div>`,'Tra cứu vé');}
}
function renderReceiptV2(b) { const t=b.trip||{}, paid=b.paymentStatus==='paid',active=['reserved','pending_payment','confirmed'].includes(b.status),copy=receiptCopy(b);shell(`<div class="container page-main"><div class="receipt-wrap">${breadcrumb('Thông tin đặt chỗ')}<div class="receipt-header"><div class="receipt-icon">${icon(paid?'check':'ticket')}</div><h1>${esc(copy.title)}</h1><p>${esc(copy.description)}</p></div><div class="print-only">Ticket4T · Thông tin đặt chỗ${sourceDemo(b)?' minh họa':''}</div><section class="card receipt-main"><div><div class="flex between"><span class="eyebrow" style="margin:0">Mã đặt chỗ</span>${statusBadge(b)}</div><div class="receipt-code">${esc(b.code)}</div><h3>${esc(t.fromName||b.fromName)} ${icon('arrow')} ${esc(t.toName||b.toName)}</h3>${timeHtml(t)}<div class="receipt-meta"><div><label>Nhà xe</label><strong>${esc(t.operatorName||b.operatorName)}</strong></div><div><label>Ngày khởi hành</label><strong>${dateLabel(t.date||b.date,true)}</strong></div><div><label>Hành khách</label><strong>${esc(b.fullName)}</strong></div><div><label>Số điện thoại</label><strong>${esc(b.phone)}</strong></div><div><label>Chỗ đã đặt</label><strong>${(b.seats||[]).map(esc).join(', ')}</strong></div><div><label>Ngày tạo</label><strong>${dateTimeLabel(b.createdAt)}</strong></div><div><label>Điểm đón</label><strong>${esc(fieldPoint(b.pickup))}</strong></div><div><label>Điểm trả</label><strong>${esc(fieldPoint(b.dropoff))}</strong></div></div></div><aside class="receipt-aside"><h3 style="font-size:16px;margin-bottom:20px">Thông tin thanh toán</h3><div class="summary-line"><span>Phương thức</span><strong>${esc(paymentMethodName(b.paymentMethod))}</strong></div><div class="summary-line"><span>Thanh toán</span><strong>${esc(copy.paymentLabel)}</strong></div><div class="summary-line"><span>Số lượng</span><strong>${b.seats?.length||0} chỗ</strong></div><div class="summary-total"><span>Tổng tiền</span><strong>${money(b.total)}</strong></div>${b.expiresAt&&active&&!paid?`<div class="notice notice-warm">${icon('clock')}<span>Giữ chỗ đến<br><strong>${dateTimeLabel(b.expiresAt)}</strong></span></div>`:''}${sourceDemo(b)?'<span class="badge badge-warm" style="margin-top:15px">Dữ liệu minh họa</span>':''}</aside></section><div class="notice receipt-notice">${icon('info')}<span>${esc(copy.notice)}</span></div><div class="receipt-actions"><button class="btn" data-action="print">${icon('print')}In / lưu PDF</button><a class="btn btn-outline" href="#/tickets">${icon('ticket')}Vé của tôi</a>${active?`<button class="btn btn-outline" data-action="cancel-booking" data-code="${esc(b.code)}" data-phone="${esc(b.phone)}">Hủy đặt chỗ</button>`:''}<a class="btn btn-outline" href="#/">Tiếp tục khám phá</a></div></div></div>`,'Mã đặt chỗ '+b.code); }

async function ticketsPageV2(version) { shell(`<div class="container page-main"><div class="lookup-wrap">${breadcrumb('Vé của tôi')}<div class="page-heading"><div class="eyebrow">Hành trình trong tầm tay</div><h1>Vé của tôi</h1><p>Tra cứu đặt chỗ bằng mã và số điện thoại đã đăng ký.</p></div><div class="card lookup-card"><form class="lookup-form" id="lookup-form"><h2>Tìm lại hành trình</h2><p>Thông tin tra cứu nằm trong xác nhận đặt chỗ của bạn.</p><div id="lookup-error" class="form-error" role="alert"></div><div class="form-field"><label for="lookup-code">Mã đặt chỗ</label><input id="lookup-code" name="code" value="${esc(new URLSearchParams(location.hash.split('?')[1]||'').get('code')||'')}" placeholder="Ví dụ: T4T1234567890" autocomplete="off" maxlength="40" required></div><div class="form-field"><label for="lookup-phone">Số điện thoại</label><input id="lookup-phone" type="tel" name="phone" placeholder="Số điện thoại dùng khi đặt" autocomplete="tel" value="${esc(state.user?.phone)}" required></div><button class="btn btn-block" type="submit">${icon('search')}Tra cứu đặt chỗ</button></form><div class="lookup-art">${icon('ticket')}<h3>Giữ một mã vé.<br>Nhớ một hành trình.</h3><p>Ngày đi, chỗ đã chọn, điểm đón và thông tin thanh toán — tất cả ở đây, khi bạn cần.</p></div></div><div class="page-heading"><h2 style="font-size:23px">Lịch sử đặt chỗ</h2><p>${state.user?'Các hành trình gắn với tài khoản của bạn.':'Đăng nhập để xem mọi hành trình trong một nơi.'}</p></div><section id="booking-history">${state.user?loading('Đang tải lịch sử…'):`<div class="card empty" style="padding:35px"><a class="btn btn-outline" href="#/login?next=tickets">${icon('user')}Đăng nhập để xem lịch sử</a></div>`}</section></div></div>`,'Vé của tôi');if(!state.user)return;try{const data=await api('/api/bookings');if(version!==state.routeVersion)return;document.getElementById('booking-history').innerHTML=data.bookings?.length?`<div class="history-list">${data.bookings.map(b=>`<article class="card history-card"><div><div class="flex wrap"><span class="badge badge-gray">${esc(b.code)}</span>${statusBadge(b)}</div><h3>${esc(b.trip?.fromName||b.fromName)} → ${esc(b.trip?.toName||b.toName)}</h3><p>${dateLabel(b.trip?.date||b.date,true)} · ${esc(b.trip?.departureTime||b.departureTime)} · ${(b.seats||[]).map(esc).join(', ')} · ${money(b.total)}</p></div><a class="btn btn-outline btn-small" href="#/booking/${encodeURIComponent(b.code)}?${qs({phone:b.phone})}">Xem đặt chỗ ${icon('arrow')}</a></article>`).join('')}</div>`:'<div class="card empty"><div class="empty-icon">'+icon('ticket')+'</div><h3>Chuyến đi đầu tiên đang chờ bạn</h3><p>Bạn chưa có đặt chỗ nào. Khám phá tuyến đường yêu thích và bắt đầu hành trình.</p><a class="btn" href="'+routeHref('ho-chi-minh','da-lat')+'">Tìm chuyến xe</a></div>';}catch(e){if(version===state.routeVersion)document.getElementById('booking-history').innerHTML=`<div class="notice notice-warm">${icon('info')}${esc(e.message)}</div>`;} }

function authPage(type) { const names={login:'Chào bạn trở lại',register:'Khởi đầu một hành trình',forgot:'Tìm lại mật khẩu',reset:'Đặt mật khẩu mới',verify:'Xác thực tài khoản'};const q=new URLSearchParams(location.hash.split('?')[1]||''),next=q.get('next')||'account';if(state.user&&type==='login'){location.hash=`#/${['account','tickets','checkout'].includes(next)?next:'account'}`;return;}const forms={
  login:`<div class="form-field"><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" autocomplete="email" placeholder="ban@email.com" required></div><div class="form-field"><label for="auth-password">Mật khẩu</label><input id="auth-password" name="password" type="password" autocomplete="current-password" required></div><a class="forgot-link" href="#/forgot-password">Quên mật khẩu?</a><button class="btn btn-block" type="submit">Đăng nhập ${icon('arrow')}</button><div class="auth-bottom">Chưa có tài khoản? <a href="#/register?next=${esc(next)}">Đăng ký</a></div>`,
  register:`<div class="form-field"><label for="auth-name">Họ và tên</label><input id="auth-name" name="fullName" autocomplete="name" placeholder="Nguyễn Văn An" minlength="2" maxlength="100" required></div><div class="form-field"><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" autocomplete="email" placeholder="ban@email.com" required></div><div class="form-field"><label for="auth-phone">Số điện thoại</label><input id="auth-phone" name="phone" type="tel" autocomplete="tel" placeholder="0901 234 567" pattern="[0-9+ ]{9,20}" required></div><div class="form-field"><label for="auth-password">Mật khẩu</label><input id="auth-password" name="password" type="password" autocomplete="new-password" minlength="10" required><small>Tối thiểu 10 ký tự, có chữ hoa, chữ thường và số.</small></div><label class="consent"><input type="checkbox" required><span>Tôi đồng ý với <a href="#/policy?tab=terms" target="_blank" rel="noopener">điều khoản</a> và <a href="#/policy?tab=privacy" target="_blank" rel="noopener">chính sách bảo mật</a>.</span></label><button class="btn btn-block" type="submit">Tạo tài khoản ${icon('arrow')}</button><div class="auth-bottom">Đã có tài khoản? <a href="#/login?next=${esc(next)}">Đăng nhập</a></div>`,
  forgot:`<div class="form-field"><label for="auth-email">Email tài khoản</label><input id="auth-email" name="email" type="email" autocomplete="email" placeholder="ban@email.com" required></div><button class="btn btn-block" type="submit">Gửi hướng dẫn đặt lại ${icon('arrow')}</button><div class="auth-bottom"><a href="#/login">Quay lại đăng nhập</a></div>`,
  reset:`<input type="hidden" name="token" value="${esc(q.get('token')||'')}"><div class="form-field"><label for="auth-password">Mật khẩu mới</label><input id="auth-password" name="password" type="password" autocomplete="new-password" minlength="10" required><small>Tối thiểu 10 ký tự, có chữ hoa, chữ thường và số.</small></div><div class="form-field"><label for="auth-confirm">Nhập lại mật khẩu mới</label><input id="auth-confirm" name="confirmPassword" type="password" autocomplete="new-password" minlength="10" required></div><button class="btn btn-block" type="submit">Lưu mật khẩu mới ${icon('arrow')}</button>`,
  verify:`<input type="hidden" name="token" value="${esc(q.get('token')||'')}"><div class="notice">${icon('mail')}<span>Xác nhận email để hoàn tất thông tin tài khoản của bạn.</span></div><button class="btn btn-block" type="submit">Xác thực email ${icon('check')}</button>`};
  const sub={login:'Đăng nhập để theo dõi và quản lý các chuyến đi.',register:'Tạo tài khoản để giữ những hành trình ở cùng một nơi.',forgot:'Nhập email, chúng tôi sẽ gửi hướng dẫn nếu tài khoản tồn tại.',reset:'Mật khẩu mới giúp bảo vệ thông tin hành trình của bạn.',verify:'Dùng liên kết được gửi tới email đăng ký của bạn.'};
  shell(`<div class="container page-main"><section class="card auth-wrap"><div class="auth-visual"><img src="/images/locationImages/nha-trang.jpg" alt="Biển Nha Trang"><div class="auth-visual-content"><div class="eyebrow">Trọn từng hành trình</div><h2>Có những nơi<br>đang chờ bạn.</h2><p>Lưu hành trình, chọn chỗ và chuẩn bị cho chuyến đi tiếp theo cùng Ticket4T.</p></div></div><form class="auth-form" id="auth-form" data-type="${type}" data-next="${esc(next)}"><h1>${names[type]}</h1><p>${sub[type]}</p><div id="auth-error" class="form-error" role="alert"></div>${forms[type]}</form></section></div>`,names[type]); }
function authSuccess(title,message) { const el=document.getElementById('auth-form');if(el)el.innerHTML=`<div class="auth-success">${icon('mail')}<h2>${esc(title)}</h2><p>${esc(message)}</p><a class="btn" href="${state.user?'#/account':'#/login'}">${state.user?'Tiếp tục đến tài khoản':'Về trang đăng nhập'} ${icon('arrow')}</a></div>`; }
function accountPage() { if(!state.user){location.hash='#/login?next=account';return;}const u=state.user;shell(`<div class="container page-main">${breadcrumb('Tài khoản')}<section class="card profile-card"><div class="profile-head"><div class="profile-avatar">${esc(initials(u.fullName))}</div><div><div class="eyebrow">Tài khoản của bạn</div><h2>${esc(u.fullName)}</h2><p>${esc(u.email)}</p></div></div><hr class="divider"><div class="summary-line"><span>Số điện thoại</span><strong>${esc(u.phone||'Chưa cập nhật')}</strong></div><div class="summary-line"><span>Xác thực email</span><strong>${u.verified?'Đã xác thực':'Chưa xác thực'}</strong></div><div class="summary-line"><span>Loại tài khoản</span><strong>${u.role==='admin'?'Quản trị viên':u.role==='operator'?'Nhà xe':'Hành khách'}</strong></div><hr class="divider"><div class="flex wrap"><a class="btn" href="#/tickets">${icon('ticket')}Vé của tôi</a>${['admin','operator'].includes(u.role)?'<a class="btn btn-outline" href="/admin">Trang quản trị</a>':''}<button class="btn btn-outline" data-action="logout">${icon('logout')}Đăng xuất</button></div></section></div>`,'Tài khoản'); }

function operatorsPage() { const ops=state.bootstrap.operators||[];shell(`<div class="container page-main">${breadcrumb('Nhà xe')}<div class="page-heading"><div class="eyebrow">Đồng hành trên mỗi cung đường</div><h1>Chọn nhà xe bạn yêu thích</h1><p>Xem thông tin, đánh giá và chuyến xe của từng nhà xe.${state.bootstrap.dataMode==='demo'?' Thông tin hiện là dữ liệu minh họa.':''}</p></div><div class="form-field" style="max-width:420px;margin-bottom:25px"><label class="sr-only" for="operator-search">Tìm tên nhà xe</label><input type="search" id="operator-search" placeholder="Tìm tên nhà xe…"></div><div class="operator-grid" id="operator-grid">${ops.map(operatorCard).join('')||'<div class="empty"><h3>Nhà xe đang được cập nhật</h3><p>Thông tin sẽ hiển thị khi nhà xe mở bán trên hệ thống.</p></div>'}</div></div>`,'Danh sách nhà xe'); }
function operatorCard(o) { return `<article class="card operator-card" data-operator-name="${esc(o.name.toLowerCase())}"><div class="operator-mark">${esc(initials(o.name))}</div><div class="flex between"><h3>${esc(o.name)}</h3>${sourceDemo(o)?'<span class="badge badge-warm">Minh họa</span>':''}</div>${ratingHtml(o)}<p>${esc(o.description || 'Xem tiện ích và lịch khởi hành để lựa chọn chuyến xe phù hợp.')}</p><a class="btn btn-outline btn-small" href="#/operators/${encodeURIComponent(o.id)}">Xem nhà xe ${icon('arrow')}</a></article>`; }
async function operatorPage(id,version) {
  shell(`<div class="container page-main">${loading('Đang tải thông tin nhà xe…')}</div>`,'Thông tin nhà xe');
  try{const data=await api(`/api/operators/${encodeURIComponent(id)}`);if(version!==state.routeVersion)return;const o=data.operator||data;renderOperator(o,data.trips||[]);loadReviews(id,'operator-reviews');}
  catch(e){if(version!==state.routeVersion)return;const o=state.bootstrap.operators.find(o=>String(o.id)===String(id));if(o){renderOperator(o,[]);loadReviews(id,'operator-reviews');}else shell(errorPage(e.message),'Nhà xe');}
}
function renderOperator(o,trips) {shell(`<div class="container page-main">${breadcrumb(o.name,`<a href="#/operators">Nhà xe</a>${icon('chevron')}`)}<section class="card operator-feature"><div class="operator-mark">${esc(initials(o.name))}</div><div><div class="eyebrow">Đồng hành cùng bạn</div><h1>${esc(o.name)}</h1><div class="flex wrap">${ratingHtml(o)}${sourceDemo(o)?'<span class="badge badge-warm">Thông tin minh họa</span>':''}</div><p>${esc(o.description||'Xem lịch xe, điểm đón và tiện ích để lựa chọn hành trình phù hợp.')}</p></div></section><div class="section-head"><div><h2 style="font-size:25px">Chuyến xe của ${esc(o.name)}</h2><p>Chọn tuyến và ngày để tìm lịch xe của nhà xe.</p></div></div><form id="operator-trip-form" data-operator="${esc(o.id)}" class="card pad"><div class="form-grid" style="grid-template-columns:1fr 1fr 1fr"><div class="form-field"><label for="op-from">Nơi xuất phát</label><select name="from" id="op-from">${locationOptions('ho-chi-minh')}</select></div><div class="form-field"><label for="op-to">Điểm đến</label><select name="to" id="op-to">${locationOptions('da-lat')}</select></div><div class="form-field"><label for="op-date">Ngày đi</label><input type="date" id="op-date" name="date" value="${today()}" min="${today()}" required></div></div><button class="btn btn-small" type="submit" style="margin-top:20px">Tìm chuyến của nhà xe ${icon('search')}</button></form>${trips.length?`<div class="trip-list" style="margin-top:25px">${trips.slice(0,4).map(tripCard).join('')}</div>`:''}<div class="section-head" style="margin-top:40px"><div><h2 style="font-size:25px">Đánh giá hành trình</h2><p>Thông tin giúp bạn cân nhắc chuyến đi.</p></div></div><section class="card pad" id="operator-reviews">${loading('Đang tải đánh giá…')}</section></div>`,o.name); }

function supportPage() { const faqs=[['Làm thế nào để đặt vé?','Chọn nơi xuất phát, điểm đến và ngày đi. So sánh chuyến xe, chọn chỗ trên sơ đồ, nhập thông tin hành khách và phương thức thanh toán. Sau khi đặt, hãy lưu mã đặt chỗ và kiểm tra trạng thái thanh toán.'],['Mã đặt chỗ có phải là vé đã thanh toán?','Mã đặt chỗ giúp bạn theo dõi hành trình và các chỗ đã giữ. Trạng thái “Đang giữ chỗ” hoặc “Chờ thanh toán” chưa có nghĩa là đã thanh toán. Chỉ trạng thái thanh toán “Đã thanh toán” mới xác nhận tiền đã được ghi nhận. Với dữ liệu minh họa, mã đặt chỗ không phải vé của nhà xe.'],['Tôi có thể chọn nhiều chỗ cùng lúc không?','Bạn có thể chọn tối đa 6 chỗ trong một lần đặt. Giá từng chỗ và tổng tiền được hiển thị trước khi xác nhận. Chỗ trống sẽ được kiểm tra lại khi hoàn tất đặt chỗ.'],['Tôi tra cứu đặt chỗ ở đâu?','Vào “Vé của tôi”, nhập mã đặt chỗ và số điện thoại đã dùng khi đặt. Nếu đăng nhập khi đặt vé, bạn cũng có thể xem lịch sử trong tài khoản.'],['Tôi có thể hủy đặt chỗ không?','Mở thông tin đặt chỗ từ “Vé của tôi” và chọn “Hủy đặt chỗ”. Hệ thống sẽ kiểm tra điều kiện hủy của chuyến, giờ khởi hành và trạng thái thanh toán. Vé đã thanh toán có thể chuyển sang trạng thái chờ hoàn tiền, không phải hoàn tiền ngay lập tức.'],['Tôi nên đến điểm đón lúc nào?','Hãy có mặt ít nhất 30 phút trước giờ khởi hành. Kiểm tra ngày đi, giờ đi và điểm đón trong thông tin đặt chỗ. Giờ đến là dự kiến và có thể thay đổi theo tình hình giao thông.'],['Vì sao chưa thấy thanh toán trực tuyến?','Thanh toán trực tuyến chỉ được mở khi cổng thanh toán đã được kết nối và cấu hình cho hệ thống. Nếu chưa mở, giao diện hiển thị phương thức thanh toán tại nhà xe và trạng thái chưa thanh toán.'],['Dữ liệu minh họa nghĩa là gì?','Dữ liệu minh họa giúp bạn trải nghiệm tìm chuyến, chọn chỗ và quản lý đặt chỗ. Nhà xe chưa kết nối trực tiếp; lịch xe, giá và đánh giá không phải dữ liệu mở bán thực tế. Không sử dụng mã minh họa để lên xe hoặc chuyển tiền cho nhà xe.']];shell(`<div class="container page-main">${breadcrumb('Trung tâm hỗ trợ')}<div class="page-heading"><div class="eyebrow">Chuẩn bị cho một chuyến đi suôn sẻ</div><h1>Chúng tôi giúp bạn sẵn sàng</h1><p>Những thông tin cần biết, từ lần đặt đầu tiên đến khi lên xe.</p></div><div class="help-layout"><aside class="help-aside">${icon('support')}<h3>Một hành trình.<br>Mọi thông tin.</h3><p>Kiểm tra mã đặt chỗ, ngày đi và điểm đón trước khi khởi hành. Bạn luôn có thể tìm lại thông tin trong “Vé của tôi”.</p><a class="btn btn-light btn-small" href="#/tickets">Tra cứu vé ${icon('arrow')}</a></aside><section class="faq-list" aria-label="Câu hỏi thường gặp">${faqs.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}</summary><p>${a}</p></details>`).join('')}</section></div></div>`,'Trung tâm hỗ trợ'); }
function policyPage() { const tab=new URLSearchParams(location.hash.split('?')[1]||'').get('tab')||'terms';const titles={terms:'Điều khoản sử dụng',privacy:'Chính sách bảo mật',cancel:'Đổi và hủy đặt chỗ'};const content={
terms:`<h2>Thông tin rõ ràng trước khi đặt</h2><p>Ticket4T cung cấp công cụ tìm chuyến, chọn chỗ và quản lý đặt chỗ. Bạn cần kiểm tra tuyến xe, ngày, giờ, điểm đón, giá và chính sách của chuyến trước khi xác nhận. Thời gian đến là dự kiến.</p><h2>Trạng thái đặt chỗ và thanh toán</h2><p>Đặt chỗ đang giữ hoặc chờ thanh toán chưa phải xác nhận đã thanh toán. Chỗ có thể hết hạn theo thời hạn hiển thị. Khi thanh toán qua cổng trực tuyến, kết quả được xác định theo thông báo giao dịch đã được xác minh từ cổng thanh toán.</p><h2>Trách nhiệm của hành khách</h2><ul><li>Cung cấp họ tên, email và số điện thoại chính xác.</li><li>Bảo mật mã đặt chỗ và tài khoản, kiểm tra thông tin trước khi lên xe.</li><li>Có mặt tại điểm đón ít nhất 30 phút trước giờ khởi hành.</li></ul><h2>Dữ liệu minh họa</h2><p>Khi có nhãn “Dữ liệu minh họa”, lịch xe, giá và đánh giá dùng cho trải nghiệm. Đặt chỗ không được gửi đến nhà xe và không tạo quyền vận chuyển. Nền tảng chỉ mở bán thực tế khi đơn vị vận hành cung cấp lịch, tồn chỗ và điều kiện dịch vụ hợp lệ.</p>`,
privacy:`<h2>Dữ liệu phục vụ hành trình</h2><p>Họ tên, email và số điện thoại được sử dụng để quản lý tài khoản, tạo và tra cứu đặt chỗ. Thông tin chỗ, điểm đón và thanh toán giúp xử lý hành trình đã chọn.</p><h2>Bảo vệ thông tin</h2><p>Mật khẩu được lưu dưới dạng đã băm. Phiên đăng nhập được quản lý bằng cookie. Thông tin thẻ thanh toán không được nhập hoặc lưu trên Ticket4T; khi được mở, giao dịch được thực hiện trên cổng thanh toán.</p><h2>Quyền truy cập</h2><p>Bạn có thể xem thông tin tài khoản và lịch sử đặt chỗ sau khi đăng nhập. Tra cứu khách vãng lai cần cả mã đặt chỗ và số điện thoại. Chỉ cung cấp các thông tin này cho người được bạn cho phép.</p><h2>Triển khai thực tế</h2><p>Đơn vị vận hành cần công bố thông tin liên hệ, thời hạn lưu trữ dữ liệu và quy trình tiếp nhận yêu cầu của hành khách trước khi mở bán. Bản trải nghiệm hiện chưa gửi dữ liệu đến nhà xe.</p>`,
cancel:`<h2>Hủy đặt chỗ chưa thanh toán</h2><p>Tra cứu đặt chỗ tại “Vé của tôi”, mở chi tiết và chọn “Hủy đặt chỗ”. Hệ thống kiểm tra điều kiện chuyến trước khi xử lý. Khi hủy thành công, các chỗ được giải phóng.</p><h2>Đặt chỗ đã thanh toán</h2><p>Hủy vé đã thanh toán có thể tạo yêu cầu hoàn tiền. Trạng thái “Chờ hoàn tiền” chưa có nghĩa là tiền đã được hoàn. Phí, thời hạn hủy và thời gian xử lý phụ thuộc chính sách chuyến và cổng thanh toán.</p><h2>Thay đổi hành trình</h2><p>Để thay ngày hoặc chuyến, hãy kiểm tra chính sách hiện hành, hủy đặt chỗ cũ khi đủ điều kiện và tạo đặt chỗ mới. Không tự ý sử dụng mã đặt chỗ cho chuyến khác.</p><h2>Thời hạn giữ chỗ</h2><p>Đặt chỗ chưa thanh toán có thể tự hết hạn và giải phóng chỗ theo thời gian hiển thị. Sau khi hết hạn, cần chọn lại chỗ trong lịch xe mới nhất.</p>`};shell(`<div class="container page-main">${breadcrumb(titles[tab]||titles.terms)}<div class="page-heading" style="max-width:850px;margin-left:auto;margin-right:auto"><div class="eyebrow">Thông tin hành trình</div><h1>${titles[tab]||titles.terms}</h1><p>Đọc và kiểm tra các điều kiện trước khi xác nhận đặt chỗ.</p></div><article class="card policy-content">${content[tab]||content.terms}</article></div>`,titles[tab]||titles.terms); }

function navigateSearch(values,form){
  const hash=`#/search?${qs(values)}`;
  if(location.hash===hash){setBusy(form,false);route().catch(error=>shell(errorPage(error.message)));}
  else location.hash=hash;
}

function updateSearch(patch) {
  const values={...readSearch(),...patch};
  if (patch.date && values.mode==='roundtrip') {
    if (values.leg==='return') {
      const outbound=v3.journey?.legs[0];
      if (outbound && values.date<(outbound.trip.arrivalDate||outbound.trip.date)) {
        toast('Ngày về cần từ ngày chiều đi đến nơi trở đi.',true);return;
      }
      values.returnDate=values.date;
      if(v3.journey){v3.journey.returnDate=values.date;persistJourney();}
    } else if(values.returnDate<values.date) values.returnDate=values.date;
  }
  location.hash=`#/search?${qs(values)}`;
}
function attachReviewForm(booking) {
  if(!state.user||booking.userId!==state.user.id||sourceDemo(booking)||booking.paymentStatus!=='paid'||booking.status!=='confirmed')return;
  const trip=booking.trip||{},arrival=new Date(`${trip.date}T${trip.departureTime}:00+07:00`).getTime()+Number(trip.durationMinutes||0)*60000;
  if(!Number.isFinite(arrival)||arrival>Date.now())return;
  const wrap=document.querySelector('.receipt-wrap');if(!wrap)return;
  wrap.insertAdjacentHTML('beforeend',`<form class="card pad form-section" id="review-form" data-code="${esc(booking.code)}"><h2>Chia sẻ về chuyến đi của bạn</h2><p>Đánh giá từ hành khách đã hoàn tất chuyến giúp mọi người chọn xe tốt hơn.</p><div id="review-error" class="form-error" role="alert"></div><div class="form-grid"><div class="form-field"><label for="review-rating">Điểm đánh giá</label><select name="rating" id="review-rating" required><option value="5">5 sao · Rất hài lòng</option><option value="4">4 sao · Hài lòng</option><option value="3">3 sao · Bình thường</option><option value="2">2 sao · Chưa hài lòng</option><option value="1">1 sao · Không hài lòng</option></select></div><div class="form-field"><label for="review-title">Tiêu đề</label><input name="title" id="review-title" maxlength="150" placeholder="Cảm nhận ngắn về chuyến đi" required></div><div class="form-field full"><label for="review-comment">Cảm nhận của bạn</label><textarea name="comment" id="review-comment" rows="4" maxlength="2000" minlength="10" placeholder="Chỗ ngồi, giờ khởi hành, trải nghiệm phục vụ…" required></textarea></div></div><button class="btn" type="submit" style="margin-top:20px">Gửi đánh giá ${icon('star')}</button></form>`);
}
function formError(id,message) { const el=document.getElementById(id);if(el){el.textContent=message;el.scrollIntoView({block:'center',behavior:'smooth'});}else toast(message,true); }
function setBusy(form,busy,label='Đang xử lý…') { const button=form.querySelector('button[type="submit"]');if(!button)return;button.dataset.busy=String(busy);if(busy){button.dataset.original=button.innerHTML;button.textContent=label;button.disabled=true;}else{button.innerHTML=button.dataset.original||'Tiếp tục';button.disabled=false;} }

document.addEventListener('submit',async event=>{
  const form=event.target;if(!(form instanceof HTMLFormElement))return;
  const id=form.id;if(!['search-form','filter-form','checkout-form','lookup-form','auth-form','operator-trip-form','review-form'].includes(id))return;event.preventDefault();
  const values=Object.fromEntries(new FormData(form));
  if(id==='review-form'){setBusy(form,true,'Đang gửi đánh giá…');try{await api('/api/reviews',{method:'POST',body:JSON.stringify({bookingCode:form.dataset.code,rating:Number(values.rating),title:values.title.trim(),comment:values.comment.trim()})});form.innerHTML=`<div class="notice">${icon('check')}<span>Cảm ơn bạn! Đánh giá đã được lưu và sẽ giúp hành khách khác lựa chọn hành trình.</span></div>`;toast('Đánh giá đã được gửi.');}catch(e){formError('review-error',e.message);}finally{setBusy(form,false);}return;}
  if(id==='search-form'||id==='operator-trip-form') { if(values.from===values.to){toast('Điểm đến cần khác nơi xuất phát.',true);return;}if(values.date<today()){toast('Vui lòng chọn ngày từ hôm nay trở đi.',true);return;}location.hash=`#/search?${qs({...values,...(id==='operator-trip-form'?{operator:form.dataset.operator}:{})})}`;return; }
  if(id==='filter-form'){if(values.minPrice&&values.maxPrice&&Number(values.minPrice)>Number(values.maxPrice)){toast('Giá thấp nhất cần nhỏ hơn giá cao nhất.',true);return;}updateSearch({...values,page:1});return;}
  if(id==='lookup-form'){setBusy(form,true,'Đang tra cứu…');document.getElementById('lookup-error').textContent='';try{const data=await api(`/api/bookings/lookup?${qs({code:values.code.trim().toUpperCase(),phone:values.phone.trim()})}`);state.lookup=data.booking;location.hash=`#/booking/${encodeURIComponent(data.booking.code)}?${qs({phone:values.phone.trim()})}`;}catch(e){formError('lookup-error',e.message);}finally{setBusy(form,false);}return;}
  if(id==='checkout-form'){setBusy(form,true,'Đang kiểm tra và đặt chỗ…');document.getElementById('checkout-error').textContent='';try{const data=await api('/api/bookings',{method:'POST',body:JSON.stringify({tripId:state.trip.id,seats:state.selected,fullName:values.fullName.trim(),phone:values.phone.trim(),email:values.email.trim(),pickup:values.pickup,dropoff:values.dropoff,paymentMethod:values.paymentMethod})});state.lookup=data.booking;sessionStorage.removeItem('ticket4t_checkout');checkoutDraft=null; if(data.paymentUrl){const payment=new URL(data.paymentUrl,location.origin);if(payment.protocol==='https:'||payment.origin===location.origin){location.assign(payment.href);return;}throw new Error('Địa chỉ thanh toán không hợp lệ. Đặt chỗ đã được tạo, hãy tra cứu lại.');}location.hash=`#/booking/${encodeURIComponent(data.booking.code)}?${qs({phone:data.booking.phone||values.phone.trim()})}`;}catch(e){formError('checkout-error',e.message);if(e.code==='SEAT_UNAVAILABLE'||e.code==='SEATS_UNAVAILABLE')toast('Chỗ vừa thay đổi. Vui lòng quay lại sơ đồ chọn chỗ.',true);}finally{setBusy(form,false);}return;}
  if(id==='auth-form'){const type=form.dataset.type;if(type==='reset'&&values.password!==values.confirmPassword){formError('auth-error','Hai mật khẩu chưa khớp. Vui lòng kiểm tra lại.');return;}if(['register','reset'].includes(type)&&(!/[A-Z]/.test(values.password)||!/[a-z]/.test(values.password)||!/[0-9]/.test(values.password))){formError('auth-error','Mật khẩu cần có chữ hoa, chữ thường và số.');return;}setBusy(form,true);document.getElementById('auth-error').textContent='';const paths={login:'login',register:'register',forgot:'forgot-password',reset:'reset-password',verify:'verify'};try{delete values.confirmPassword;const data=await api(`/api/auth/${paths[type]}`,{method:'POST',body:JSON.stringify(values)});if(type==='login'){state.user=data.user;toast('Đăng nhập thành công. Chào bạn trở lại!');location.hash=`#/${['account','tickets','checkout'].includes(form.dataset.next)?form.dataset.next:'account'}`;}else if(type==='register'){state.user=data.user||null;authSuccess('Tài khoản đã được tạo',state.bootstrap.emailEnabled?'Hãy kiểm tra email để xác thực tài khoản. Bạn có thể tiếp tục quản lý hành trình trong tài khoản của mình.':'Bạn có thể tiếp tục quản lý hành trình trong tài khoản. Tính năng gửi email hiện chưa được mở trên phiên bản trải nghiệm.');}else if(type==='forgot'){authSuccess('Kiểm tra email của bạn',data.message||'Nếu email có trong hệ thống, hướng dẫn đặt lại mật khẩu sẽ được gửi tới bạn.');}else if(type==='reset'){state.user=null;authSuccess('Mật khẩu đã được cập nhật','Bạn có thể đăng nhập bằng mật khẩu mới.');}else{if(data.user)state.user=data.user;else if(state.user)state.user.verified=true;authSuccess('Email đã được xác thực',data.message||'Tài khoản đã được xác thực. Bạn có thể đăng nhập để tiếp tục.');}}catch(e){formError('auth-error',e.message);}finally{setBusy(form,false);} }
});

document.addEventListener('click',async event=>{
  const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;
  if(action==='location-picker'){openLocationPicker(target.dataset.target);return;}
  if(action==='menu'){const nav=document.getElementById('main-nav');nav.classList.toggle('mobile-open');target.setAttribute('aria-expanded',nav.classList.contains('mobile-open'));}
  if(action==='retry'){state.bootstrap?route():init();}
  if(action==='swap'){const from=document.getElementById('search-from'),to=document.getElementById('search-to');const v=from.value;from.value=to.value;to.value=v;}
  if(action==='change-date')updateSearch({date:target.dataset.date,page:1});
  if(action==='clear-filters')updateSearch({type:'',operator:'',minPrice:'',maxPrice:'',time:'',page:1});
  if(action==='page')updateSearch({page:target.dataset.page});
  if(action==='filters'){document.getElementById('filter-form').classList.toggle('open');target.setAttribute('aria-expanded',document.getElementById('filter-form').classList.contains('open'));}
  if(action==='seat'){if(v3.continuing||state.trip?.bookingOpen===false)return;const label=target.dataset.label;if(state.selected.includes(label))state.selected=state.selected.filter(s=>s!==label);else if(state.selected.length>=6){toast('Bạn có thể chọn tối đa 6 chỗ mỗi lần đặt.',true);return;}else state.selected.push(label);target.classList.toggle('selected',state.selected.includes(label));target.setAttribute('aria-pressed',state.selected.includes(label));document.getElementById('seat-summary').innerHTML=seatSummary();}
  if(action==='trip-tab'){state.seatTab=target.dataset.tab;document.querySelectorAll('.tab-button').forEach(el=>{const active=el.dataset.tab===state.seatTab;el.classList.toggle('active',active);el.setAttribute('aria-selected',active);});document.getElementById('trip-tab-content').innerHTML=tripTabContent();if(state.seatTab==='reviews')loadReviews(state.trip.operatorId);}
  if(action==='refresh-seats'){target.disabled=true;try{await pollSeats(true);}finally{if(target.isConnected)target.disabled=false;}}
  if(action==='checkout'){if(!state.selected.length)return;saveDraft();location.hash='#/checkout';}
  if(action==='print')window.print();
  if(action==='logout'){try{await api('/api/auth/logout',{method:'POST',body:'{}'});state.user=null;toast('Bạn đã đăng xuất.');location.hash='#/';}catch(e){toast(e.message,true);}}
  if(action==='cancel-booking'){const ok=await confirmModal('Hủy đặt chỗ này?', 'Các chỗ sẽ được giải phóng sau khi hủy thành công. Với đặt chỗ đã thanh toán, tiền hoàn sẽ được xử lý theo chính sách và không ghi nhận hoàn ngay lập tức.', 'Hủy đặt chỗ');if(!ok)return;target.disabled=true;try{const data=await api(`/api/bookings/${encodeURIComponent(target.dataset.code)}/cancel`,{method:'POST',body:JSON.stringify({phone:target.dataset.phone})});toast(data.message||'Đặt chỗ đã được cập nhật.');if(data.booking){state.lookup=data.booking;renderReceipt(data.booking);}else route();}catch(e){toast(e.message,true);}finally{target.disabled=false;}}
});
document.addEventListener('change',event=>{if(event.target.id==='sort-select')updateSearch({sort:event.target.value,page:1});if(event.target.closest('#filter-form')&&['radio','checkbox'].includes(event.target.type)){const form=document.getElementById('filter-form');updateSearch({...Object.fromEntries(new FormData(form)),page:1});}});
document.addEventListener('input',event=>{if(event.target.id==='operator-search'){const value=event.target.value.toLowerCase().trim();document.querySelectorAll('[data-operator-name]').forEach(el=>{el.hidden=!el.dataset.operatorName.includes(value);});}});

function confirmModal(title,message,label) { return new Promise(resolve=>{const region=document.getElementById('modal-region'),previous=document.activeElement;region.innerHTML=`<div class="modal-backdrop"><section class="modal-box" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${esc(title)}</h2><p>${esc(message)}</p><div class="modal-actions"><button class="btn btn-outline" id="modal-cancel">Giữ đặt chỗ</button><button class="btn btn-danger" id="modal-confirm">${esc(label)}</button></div></section></div>`;const no=document.getElementById('modal-cancel'),yes=document.getElementById('modal-confirm');no.focus();const done=value=>{region.innerHTML='';document.removeEventListener('keydown',keyHandler);if(previous?.isConnected)previous.focus();resolve(value);};const keyHandler=e=>{if(e.key==='Escape')done(false);if(e.key==='Tab'){if(e.shiftKey&&document.activeElement===no){e.preventDefault();yes.focus();}else if(!e.shiftKey&&document.activeElement===yes){e.preventDefault();no.focus();}}};no.addEventListener('click',()=>done(false),{once:true});yes.addEventListener('click',()=>done(true),{once:true});region.firstElementChild.addEventListener('click',e=>{if(e.target===region.firstElementChild)done(false);});document.addEventListener('keydown',keyHandler);}); }

async function routeV2() {
  const version=++state.routeVersion;const path=(location.hash||'#/').slice(1).split('?')[0].replace(/\/$/,'')||'/';window.scrollTo({top:0});
  if(!state.bootstrap){shell(errorPage('Chưa tải được dữ liệu hệ thống. Vui lòng kiểm tra kết nối và thử lại.'));return;}
  if(path==='/')home();else if(path==='/search')await searchPage(version);else if(path.startsWith('/trip/'))await tripPage(decodeURIComponent(path.split('/')[2]),version);else if(path==='/checkout')await checkoutPage(version);else if(path.startsWith('/booking/'))await bookingPage(decodeURIComponent(path.split('/')[2]),version);else if(path==='/tickets'||path==='/lookup')await ticketsPage(version);else if(path==='/login')authPage('login');else if(path==='/register')authPage('register');else if(path==='/forgot-password')authPage('forgot');else if(path==='/reset-password')authPage('reset');else if(path==='/verify'||path==='/verify-email')authPage('verify');else if(path==='/account')accountPage();else if(path==='/operators')operatorsPage();else if(path.startsWith('/operators/'))await operatorPage(decodeURIComponent(path.split('/')[2]),version);else if(path==='/support')supportPage();else if(path==='/policy')policyPage();else shell(`<div class="container page-main"><div class="empty"><h1>Chúng ta hơi lạc đường rồi</h1><p>Trang bạn tìm chưa có trên hành trình này.</p><a class="btn" href="#/">Về trang chủ ${icon('arrow')}</a></div></div>`,'Không tìm thấy trang');
}

window.addEventListener('hashchange',()=>route().catch(e=>shell(errorPage(e.message))));
async function init() { try { const [bootstrap,user]=await Promise.allSettled([api('/api/bootstrap'),api('/api/auth/me')]);if(bootstrap.status==='rejected')throw bootstrap.reason;state.bootstrap=bootstrap.value;state.user=user.status==='fulfilled'?user.value.user:null;await route(); }catch(e){shell(errorPage(e.message));} }

// Journey tools keep the original booking workflow and selectors intact.
function storedJSON(key,area=localStorage,fallback=[]) {
  try {
    const value=JSON.parse(area.getItem(key)||'null');
    if(Array.isArray(fallback))return Array.isArray(value)?value.filter(item=>item&&typeof item==='object'&&item.id).slice(0,key==='ticket4t_compare'?3:50):fallback;
    if(!value||typeof value!=='object'||Array.isArray(value))return fallback;
    if(key==='ticket4t_reschedule')return value.booking?.code&&value.booking.trip?value:fallback;
    return Array.isArray(value.legs)&&value.legs.every(leg=>leg&&leg.trip&&Array.isArray(leg.seats))?value:fallback;
  }catch{return fallback;}
}
const v3={favorites:storedJSON('ticket4t_favorites'),compare:storedJSON('ticket4t_compare'),trips:new Map(),journey:storedJSON('ticket4t_journey',sessionStorage,null),quote:null,reschedule:storedJSON('ticket4t_reschedule',sessionStorage,null),promotions:[],polling:false};
let checkoutAttempt=null,bookingPolling=null;
try{const attempt=JSON.parse(sessionStorage.getItem('ticket4t_checkout_attempt')||'null');if(attempt&&typeof attempt.key==='string'&&typeof attempt.body==='string'&&['/api/bookings','/api/orders'].includes(attempt.path)&&Date.now()-attempt.createdAt<86400000){JSON.parse(attempt.body);checkoutAttempt=attempt;}}catch{}
function persistCheckoutAttempt(){try{if(checkoutAttempt)sessionStorage.setItem('ticket4t_checkout_attempt',JSON.stringify(checkoutAttempt));else sessionStorage.removeItem('ticket4t_checkout_attempt');}catch{}}
function clearCheckoutAttempt(key){if(!key||checkoutAttempt?.key===key){checkoutAttempt=null;persistCheckoutAttempt();}}
function rememberPaymentBooking(booking){if(!onlinePaymentMethods.includes(booking?.paymentMethod))return;try{sessionStorage.setItem('ticket4t_payment_return',JSON.stringify({code:booking.code,phone:booking.phone,until:Date.now()+86400000}));}catch{}}
function paymentContact(code){try{const contact=JSON.parse(sessionStorage.getItem('ticket4t_payment_return')||'null');return contact?.code===code&&contact.until>Date.now()&&typeof contact.phone==='string'?contact.phone:'';}catch{return '';}}
function paymentDestination(value){const url=new URL(value,location.origin);if(url.protocol==='https:'||url.protocol==='http:'&&url.origin===location.origin)return url.href;throw new Error('Địa chỉ thanh toán không hợp lệ. Vui lòng tra cứu lại đặt chỗ.');}
function checkoutRequest(form){
  const values=Object.fromEntries(new FormData(form)),legs=checkoutLegs();
  const common={fullName:(values.fullName||'').trim(),email:(values.email||'').trim(),phone:(values.phone||'').trim(),paymentMethod:values.paymentMethod,couponCode:(values.couponCode||'').trim().toUpperCase()};
  const items=legs.map((leg,i)=>({tripId:leg.tripId,seats:[...leg.seats],pickup:i?values.returnPickup:values.pickup,dropoff:i?values.returnDropoff:values.dropoff,holdToken:leg.hold?.token}));
  return {values,legs,path:legs.length===2?'/api/orders':'/api/bookings',body:JSON.stringify(legs.length===2?{...common,legs:items,paymentMethod:'cash'}:{...common,...items[0]})};
}
function replayableCheckout(form=document.getElementById('checkout-form')){if(!form||!checkoutAttempt)return false;const request=checkoutRequest(form);return request.path===checkoutAttempt.path&&request.body===checkoutAttempt.body;}
function attemptMatchesDraft(){if(!checkoutAttempt)return false;try{const input=JSON.parse(checkoutAttempt.body),items=input.legs||[input],legs=checkoutLegs();return items.length===legs.length&&items.every((item,i)=>item.tripId===legs[i].tripId&&JSON.stringify(item.seats)===JSON.stringify(legs[i].seats)&&item.holdToken===legs[i].hold?.token);}catch{return false;}}
function restoreCheckoutAttempt(form){if(!attemptMatchesDraft())return;const input=JSON.parse(checkoutAttempt.body),items=input.legs||[input],fields={...input,pickup:items[0].pickup,dropoff:items[0].dropoff,returnPickup:items[1]?.pickup,returnDropoff:items[1]?.dropoff};for(const [name,value] of Object.entries(fields)){if(typeof value!=='string')continue;const field=form.elements.namedItem(name);if(field instanceof RadioNodeList)field.value=value;else if(field)field.value=value;}if(checkoutAttempt.quote)v3.quote=checkoutAttempt.quote;form.insertAdjacentHTML('afterbegin',`<div class="notice notice-warm" data-checkout-recovery>${icon('info')}<span>Yêu cầu trước chưa nhận đủ kết quả. Giữ nguyên thông tin và xác nhận lại để lấy kết quả của cùng đặt chỗ.</span></div>`);}
function queryValues(){return Object.fromEntries(new URLSearchParams(location.hash.split('?')[1]||''));}
function isSelectable(seat){return seat.status==='available'||seat.ownHold===true;}
function persistJourney(){if(v3.journey)sessionStorage.setItem('ticket4t_journey',JSON.stringify(v3.journey));else sessionStorage.removeItem('ticket4t_journey');}
function persistDraft(){if(checkoutDraft)sessionStorage.setItem('ticket4t_checkout',JSON.stringify(checkoutDraft));else sessionStorage.removeItem('ticket4t_checkout');}
function legSubtotal(leg){return (leg.trip?.seats||[]).filter(s=>leg.seats.includes(s.label)).reduce((sum,s)=>sum+Number(s.price||leg.trip.price),0)||leg.seats.length*Number(leg.trip?.price||0);}
function checkoutLegs(){if(checkoutDraft?.legs?.length)return checkoutDraft.legs;return checkoutDraft?.trip?[{tripId:checkoutDraft.tripId,seats:checkoutDraft.seats,trip:checkoutDraft.trip,hold:checkoutDraft.hold}]:[];}
function draftSubtotal(){return checkoutLegs().reduce((sum,leg)=>sum+legSubtotal(leg),0);}
function holdAlive(hold){return Boolean(hold?.token&&new Date(hold.expiresAt).getTime()>Date.now());}
function activeHolds(){const legs=checkoutLegs();return (legs.length?legs:v3.journey?.legs||[]).map(leg=>leg.hold).filter(Boolean);}
function tripContextHref(t){const q=queryValues();if(q.reschedule||(location.hash||'').startsWith('#/reschedule/'))return `#/trip/${encodeURIComponent(t.id)}?${qs({reschedule:q.reschedule||v3.reschedule?.booking?.code,phone:q.phone||v3.reschedule?.booking?.phone})}`;return `#/trip/${encodeURIComponent(t.id)}${q.mode==='roundtrip'?`?${qs({mode:'roundtrip',returnDate:q.returnDate,leg:q.leg||'outbound'})}`:''}`;}
function summaryTrip(t){return Object.fromEntries(['id','operatorId','operatorName','rating','reviewCount','type','typeName','from','to','fromName','toName','date','departureTime','arrivalTime','arrivalDate','durationMinutes','price','totalSeats','availableSeats','image','amenities','source'].map(k=>[k,t[k]]));}

function searchBox(values={},inline=false){if(values.mode==='roundtrip'&&values.leg==='return'){return searchBoxV2(values,inline).replace('id="search-form">',`id="search-form"><div class="journey-switch"><strong>Khứ hồi · Chọn chiều về</strong><input type="hidden" name="tripMode" value="roundtrip"><input type="hidden" name="returnDate" value="${esc(values.date)}"></div>`).replace('Ngày khởi hành','Ngày về');}const mode=values.mode||'oneway';let html=searchBoxV2(values,inline);const returnDate=values.returnDate||addDays(values.date||today(),1);html=html.replace('id="search-form">',`id="search-form"><div class="journey-switch" role="group" aria-label="Loại hành trình"><label><input type="radio" name="tripMode" value="oneway" ${mode!=='roundtrip'?'checked':''}>Một chiều</label><label><input type="radio" name="tripMode" value="roundtrip" ${mode==='roundtrip'?'checked':''}>Khứ hồi</label><a href="#/promotions" class="journey-offer">${icon('ticket')}Ưu đãi đang mở</a></div>`);html=html.replace('<button class="btn" type="submit">',`<div class="search-field return-field" ${mode!=='roundtrip'?'hidden':''}>${icon('calendar')}<div class="field-inner"><label for="search-return-date">Ngày về</label><input type="date" id="search-return-date" name="returnDate" min="${esc(values.date||today())}" value="${esc(returnDate)}" ${mode!=='roundtrip'?'disabled':''} required></div></div><button class="btn" type="submit">`);return mode==='roundtrip'?html.replace('class="search-box','class="search-box roundtrip-search'):html;}
function readSearch(){const base=readSearchV2(),q=queryValues();return {...base,mode:q.mode||'oneway',returnDate:q.returnDate||'',leg:q.leg||'outbound',pickup:q.pickup||'',dropoff:q.dropoff||'',q:q.q||''};}
function filterPanel(p){return filterPanelV2(p).replace('<div class="filter-group"><h4>Khoảng giá',`<div class="filter-group"><h4>Điểm đón và trả</h4><label for="filter-pickup">Điểm đón</label><input id="filter-pickup" type="search" name="pickup" placeholder="Ví dụ: Bến xe" value="${esc(p.pickup)}"><label for="filter-dropoff">Điểm trả</label><input id="filter-dropoff" type="search" name="dropoff" placeholder="Ví dụ: Văn phòng" value="${esc(p.dropoff)}"><label for="filter-keyword">Từ khóa</label><input id="filter-keyword" type="search" name="q" placeholder="Tên xe, tuyến, tiện ích…" value="${esc(p.q)}"></div><div class="filter-group"><h4>Khoảng giá`);}
function home(){homeV2();const banner=document.querySelector('.journey-banner');if(banner)banner.parentElement.insertAdjacentHTML('beforebegin',`<section class="section promotions-home"><div class="container"><div class="section-head"><div><div class="eyebrow">Thêm một lý do để lên đường</div><h2>Ưu đãi cho hành trình</h2><p>Mã ưu đãi được kiểm tra theo chuyến và điều kiện sử dụng.</p></div><a class="text-link" href="#/promotions">Xem tất cả ${icon('arrow')}</a></div><div id="home-promotions" class="promotion-grid">${loading('Đang tải ưu đãi…')}</div></div></section>`);loadPromotions('home-promotions',3);}
async function searchPage(version){await searchPageV2(version);if(version!==state.routeVersion)return;const results=document.getElementById('search-results');if(!results)return;const q=readSearch();results.insertAdjacentHTML('afterbegin',`<div class="search-utilities"><a class="text-link" href="#/favorites" id="favorites-shortcut">${icon('heart')}Đã lưu (${v3.favorites.length})</a><a class="text-link" href="#/compare" id="compare-shortcut">So sánh (${v3.compare.length}/3) ${icon('swap')}</a></div>`);if(q.mode==='roundtrip'){const box=document.querySelector('.page-heading');box?.insertAdjacentHTML('afterend',`<div class="notice journey-status">${icon('swap')}<div><strong>${q.leg==='return'?'Bước 2 · Chọn chuyến về':'Bước 1 · Chọn chuyến đi'}</strong><p>${q.leg==='return'&&v3.journey?.legs[0]?`${esc(v3.journey.legs[0].trip.operatorName)} · Chiều đi ${dateLabel(v3.journey.legs[0].trip.date)} ${esc(v3.journey.legs[0].trip.departureTime)} · Chỗ ${v3.journey.legs[0].seats.map(esc).join(', ')}<br>`:''}Khứ hồi được đặt cùng một đơn, hiện thanh toán tại nhà xe.${q.leg==='return'?'<br><span class="hold-clock" data-hold-clock></span><button class="text-link" data-action="restart-outbound" style="margin-top:8px">Chọn lại chiều đi</button>':''}</p></div></div>`);updateHoldClocks();}}
function tripCard(t){v3.trips.set(String(t.id),summaryTrip(t));let html=tripCardV2(t);html=html.split(`#/trip/${encodeURIComponent(t.id)}`).join(tripContextHref(t));const favorite=v3.favorites.some(item=>String(item.id)===String(t.id)),compare=v3.compare.some(item=>String(item.id)===String(t.id));return html.replace('</article>',`<div class="trip-utilities"><button class="trip-tool ${favorite?'is-saved':''}" data-action="favorite" data-trip-id="${esc(t.id)}" aria-pressed="${favorite}">${icon('heart')}${favorite?'Đã lưu':'Lưu chuyến'}</button><button class="trip-tool ${compare?'is-saved':''}" data-action="compare" data-trip-id="${esc(t.id)}" aria-pressed="${compare}">${icon('swap')}${compare?'Đã chọn so sánh':'Thêm so sánh'}</button></div></article>`);}
async function tripPage(id,version){await tripPageV2(id,version);if(version!==state.routeVersion||!state.trip)return;const leg=checkoutLegs().find(leg=>String(leg.tripId)===String(id))||v3.journey?.legs.find(leg=>String(leg.tripId)===String(id));if(leg&&holdAlive(leg.hold)){state.selected=leg.seats.filter(label=>state.trip.seats.some(s=>s.label===label&&isSelectable(s)));renderTrip();}const q=queryValues();if(q.reschedule&&(!v3.reschedule||v3.reschedule.booking.code!==q.reschedule)){try{const data=await api(`/api/bookings/lookup?${qs({code:q.reschedule,phone:q.phone})}`);if(version!==state.routeVersion)return;v3.reschedule={booking:data.booking};sessionStorage.setItem('ticket4t_reschedule',JSON.stringify(v3.reschedule));document.getElementById('seat-summary').innerHTML=seatSummary();}catch(e){toast(e.message,true);}}}
function renderTrip(){renderTripV2();if(state.trip.bookingOpen===false)document.querySelector('.detail-heading')?.insertAdjacentHTML('afterend',`<div class="notice notice-warm booking-closed" role="status">${icon('clock')}<span>Chuyến này đã đóng bán trực tuyến. Vui lòng chọn chuyến khởi hành sau ít nhất 30 phút.</span></div>`);const q=queryValues();if(q.mode==='roundtrip')document.querySelector('.detail-heading')?.insertAdjacentHTML('afterend',`<div class="notice journey-status">${icon('swap')}<span>${q.leg==='return'?'Chiều về':'Chiều đi'} · Khứ hồi · Ngày về ${dateLabel(q.returnDate,true)}${q.leg==='return'?'<br><span data-hold-clock></span><button class="text-link" data-action="restart-outbound" style="margin-top:8px">Chọn lại chiều đi</button>':''}</span></div>`);if(q.reschedule)document.querySelector('.detail-heading')?.insertAdjacentHTML('afterend',`<div class="notice journey-status">${icon('refresh')}<span>Đổi chuyến cho mã ${esc(q.reschedule)}. Nhà xe, tuyến và điều kiện giá được kiểm tra khi xác nhận.</span></div>`);updateHoldClocks();}
function seatSummary(){let html=seatSummaryV2();if(state.trip.bookingOpen===false)html=html.replace('data-action="checkout"','data-action="checkout" disabled').replace('Tiếp tục đặt vé','Đã đóng bán trực tuyến');const q=queryValues();if(q.reschedule)html=html.replace('Tiếp tục đặt vé','Tiếp tục đổi chuyến');else if(q.mode==='roundtrip'&&q.leg!=='return')html=html.replace('Tiếp tục đặt vé','Chọn chuyến về');if(activeHolds().length)html=html.replace('<h3>Hành trình của bạn</h3>',`<h3>Hành trình của bạn</h3><div class="hold-banner"><span data-hold-clock></span></div>`);return html;}
function tripTabContent(){let html=tripTabContentV2();if(state.seatTab==='info'&&state.trip.stops?.length){html=`${stopsTimeline(state.trip)}${html}`;}return html;}
function stopsTimeline(trip){return `<section class="itinerary"><h3 class="info-title">Lộ trình dự kiến</h3><p class="muted text-small">Các điểm dừng để tham khảo hành trình. Đặt chỗ theo toàn tuyến đã chọn.</p><ol class="stop-timeline">${trip.stops.map((stop,i)=>`<li><span class="stop-node ${i===0||i===trip.stops.length-1?'endpoint':''}"></span><div><strong>${esc(stop.name)}</strong><p>${esc(stop.address||'')}</p><small>${stop.estimatedAt?dateTimeLabel(stop.estimatedAt):`Sau ${duration(stop.offsetMinutes||0)} từ giờ khởi hành`} · ${stop.kind==='rest'?'Dừng nghỉ':stop.kind==='pickup'?'Điểm đón':stop.kind==='dropoff'?'Điểm trả':'Điểm trên lộ trình'}${stop.isDemo?' · Minh họa':''}</small></div></li>`).join('')}</ol></section>`;}

async function releaseHold(hold){if(!hold?.token)return;try{await api(`/api/holds/${encodeURIComponent(hold.token)}`,{method:'DELETE'});}catch{}}
async function resetJourney(){const holds=[...checkoutLegs(),...(v3.journey?.legs||[])].map(leg=>leg.hold).filter(Boolean);await Promise.allSettled([...new Map(holds.map(hold=>[hold.token,hold])).values()].map(releaseHold));v3.journey=null;checkoutDraft=null;v3.quote=null;persistJourney();persistDraft();}
async function holdSelection(t=state.trip,selected=[...state.selected]){const existing=[...checkoutLegs(),...(v3.journey?.legs||[])].find(leg=>String(leg.tripId)===String(t.id)&&holdAlive(leg.hold)&&leg.seats.length===selected.length&&selected.every(label=>leg.seats.includes(label)));if(existing)return existing.hold;const old=[...checkoutLegs(),...(v3.journey?.legs||[])].filter(leg=>String(leg.tripId)===String(t.id));await Promise.allSettled(old.map(leg=>releaseHold(leg.hold)));const data=await api('/api/holds',{method:'POST',body:JSON.stringify({tripId:t.id,seats:selected})});return data.hold;}
async function continueJourney(button){if(!state.selected.length||v3.continuing||state.trip?.bookingOpen===false)return;v3.continuing=true;const q=queryValues(),version=state.routeVersion,trip=state.trip,seats=[...state.selected];button.disabled=true;try{if(q.mode==='roundtrip'&&q.leg==='return'){const outbound=v3.journey?.legs[0];if(!outbound||!holdAlive(outbound.hold))throw new Error('Chỗ chiều đi đã hết thời gian giữ. Hãy quay lại chọn chiều đi.');const arrival=new Date(`${outbound.trip.arrivalDate||outbound.trip.date}T${outbound.trip.arrivalTime}:00+07:00`).getTime();const departure=new Date(`${state.trip.date}T${state.trip.departureTime}:00+07:00`).getTime();if(departure<=arrival)throw new Error('Chuyến về cần khởi hành sau khi chuyến đi đến nơi. Vui lòng chọn chuyến về muộn hơn.');if(state.selected.length!==outbound.seats.length)throw new Error(`Vui lòng chọn ${outbound.seats.length} chỗ cho chiều về để khớp chiều đi.`);}
    if(q.mode!=='roundtrip'){
      const unrelated=[...checkoutLegs(),...(v3.journey?.legs||[])].filter(item=>String(item.tripId)!==String(trip.id));
      await Promise.allSettled([...new Map(unrelated.filter(item=>item.hold).map(item=>[item.hold.token,item.hold])).values()].map(releaseHold));
      if(version!==state.routeVersion)return;
    }
    const hold=await holdSelection(trip,seats);if(version!==state.routeVersion){await releaseHold(hold);return;}const leg={tripId:trip.id,seats,trip,hold};v3.quote=null;
    if(q.mode!=='roundtrip'){await Promise.allSettled([...checkoutLegs(),...(v3.journey?.legs||[])].filter(item=>item.hold?.token!==hold.token).map(item=>releaseHold(item.hold)));v3.journey=null;persistJourney();}
    if(q.reschedule){checkoutDraft={tripId:leg.tripId,seats:leg.seats,trip:leg.trip,hold,legs:[leg],mode:'reschedule'};persistDraft();location.hash=`#/reschedule/${encodeURIComponent(q.reschedule)}?${qs({phone:q.phone||v3.reschedule?.booking?.phone,confirm:1})}`;return;}
    if(q.mode==='roundtrip'&&q.leg!=='return'){const returnDate=q.returnDate||addDays(state.trip.date,1);if(returnDate<(state.trip.arrivalDate||state.trip.date)){await releaseHold(hold);throw new Error('Ngày về cần từ ngày chuyến đi đến nơi trở đi.');}await Promise.allSettled([...checkoutLegs(),...(v3.journey?.legs||[])].filter(item=>item.tripId!==leg.tripId).map(item=>releaseHold(item.hold)));checkoutDraft=null;persistDraft();v3.journey={mode:'roundtrip',returnDate,legs:[leg]};persistJourney();location.hash=`#/search?${qs({from:state.trip.to,to:state.trip.from,date:returnDate,mode:'roundtrip',returnDate,leg:'return'})}`;return;}
    const legs=q.mode==='roundtrip'?[v3.journey.legs[0],leg]:[leg];checkoutDraft={tripId:leg.tripId,seats:leg.seats,trip:leg.trip,hold,legs,mode:q.mode==='roundtrip'?'roundtrip':'oneway'};persistDraft();if(legs.length===2){v3.journey.legs=legs;persistJourney();}location.hash='#/checkout';
  }catch(e){toast(e.message,true);}finally{v3.continuing=false;if(button.isConnected)button.disabled=!state.selected.length;}}

async function checkoutPage(version){if(!checkoutDraft?.legs?.length){if(!checkoutDraft?.tripId||!checkoutDraft.seats?.length){await checkoutPageV2(version);return;}try{const data=await api('/api/holds',{method:'POST',body:JSON.stringify({tripId:checkoutDraft.tripId,seats:checkoutDraft.seats})});checkoutDraft.legs=[{tripId:checkoutDraft.tripId,seats:checkoutDraft.seats,trip:checkoutDraft.trip,hold:data.hold}];checkoutDraft.hold=data.hold;persistDraft();}catch(e){if(version===state.routeVersion)shell(errorPage(e.message),'Đặt vé');return;}}shell(`<div class="container page-main">${loading('Đang kiểm tra chỗ giữ cho hành trình…')}</div>`,'Đặt vé');try{const fresh=await Promise.all(checkoutLegs().map(async leg=>{const data=await api(`/api/trips/${encodeURIComponent(leg.tripId)}`);return {...leg,trip:data.trip||data};}));if(version!==state.routeVersion)return;if(fresh.some(leg=>leg.trip.bookingOpen===false)&&!attemptMatchesDraft())throw new Error('Một chuyến trong hành trình đã đóng bán. Vui lòng chọn chuyến khác.');checkoutDraft.legs=fresh;persistDraft();const unavailable=fresh.find(leg=>leg.seats.some(label=>!leg.trip.seats.some(s=>s.label===label&&isSelectable(s))));if(unavailable&&!attemptMatchesDraft())throw new Error('Một số chỗ vừa thay đổi. Vui lòng quay lại chọn chỗ.');state.trip=fresh[0].trip;state.selected=fresh[0].seats;renderCheckout();}catch(e){if(version===state.routeVersion)shell(errorPage(e.message),'Đặt vé');}}
function renderCheckout(){renderCheckoutV2();const legs=checkoutLegs(),form=document.getElementById('checkout-form');if(!form)return;
  if(legs.length===2){
    const editHref=`#/trip/${encodeURIComponent(legs[0].tripId)}?${qs({mode:'roundtrip',returnDate:legs[1].trip.date,leg:'outbound'})}`;
    document.querySelectorAll(`a[href="#/trip/${encodeURIComponent(legs[0].tripId)}"]`).forEach(link=>link.href=editHref);
  }
form.insertAdjacentHTML('afterbegin',`<div class="hold-banner checkout-hold">${icon('clock')}<div><strong>Chỗ được giữ riêng cho bạn</strong><span data-hold-clock></span><button type="button" class="text-link" data-action="renew-holds" hidden>Kiểm tra và giữ lại chỗ</button></div></div>`);if(legs.length===2){const sections=form.querySelectorAll('.form-section');sections[1]?.querySelector('h2')?.replaceChildren(document.createTextNode('Điểm đón và trả · Chiều đi'));sections[1]?.insertAdjacentHTML('afterend',`<section class="card pad form-section"><h2>Điểm đón và trả · Chiều về</h2><p>${esc(legs[1].trip.fromName)} → ${esc(legs[1].trip.toName)} · ${dateLabel(legs[1].trip.date,true)} · ${esc(legs[1].trip.departureTime)}</p><div class="form-grid"><div class="form-field"><label for="return-pickup">Điểm đón chiều về *</label><select id="return-pickup" name="returnPickup" required>${pointOptions(legs[1].trip.pickupPoints)}</select></div><div class="form-field"><label for="return-dropoff">Điểm trả chiều về *</label><select id="return-dropoff" name="returnDropoff" required>${pointOptions(legs[1].trip.dropoffPoints)}</select></div></div></section>`);form.querySelectorAll('.payment-option input').forEach(input=>{if(onlinePaymentMethods.includes(input.value))input.closest('.payment-option').remove();});form.querySelector('.payment-options')?.insertAdjacentHTML('afterend',`<div class="notice roundtrip-payment">${icon('swap')}<span>Hai chiều được đặt cùng một đơn. Hành trình khứ hồi hiện hỗ trợ thanh toán tại nhà xe.</span></div>`);const aside=document.querySelector('.detail-layout>aside');aside.innerHTML=`<div class="card summary-card"><h3>Hành trình khứ hồi</h3>${legs.map((leg,i)=>`<div class="order-leg-summary"><span class="badge">${i?'Chiều về':'Chiều đi'}</span><h4>${esc(leg.trip.fromName)} → ${esc(leg.trip.toName)}</h4><p>${esc(leg.trip.operatorName)}<br>${dateLabel(leg.trip.date,true)} · ${esc(leg.trip.departureTime)}<br>Chỗ ${leg.seats.map(esc).join(', ')}</p><strong>${money(legSubtotal(leg))}</strong></div>`).join('')}<div id="checkout-savings"></div><div class="summary-total"><span>Tổng thanh toán</span><strong data-checkout-total>${money(draftSubtotal())}</strong></div><p class="summary-note">Giá và ưu đãi được kiểm tra lại khi tạo đơn. ${legs.some(leg=>sourceDemo(leg.trip))?'Đây là hành trình minh họa.':''}</p></div>`;}else{const total=document.querySelector('.summary-total strong');if(total)total.setAttribute('data-checkout-total','');total?.closest('.summary-total').insertAdjacentHTML('beforebegin','<div id="checkout-savings"></div>');}
    const paymentSection=form.querySelector('.payment-options')?.closest('.form-section');paymentSection?.insertAdjacentHTML('afterend',`<section class="card pad form-section"><h2>Ưu đãi cho hành trình</h2><p>Mã được kiểm tra theo tổng tiền, tuyến xe và số điện thoại.</p><div class="coupon-input"><label class="sr-only" for="coupon-code">Mã ưu đãi</label><input id="coupon-code" name="couponCode" placeholder="Nhập mã ưu đãi" value="${esc(v3.quote?.couponCode||sessionStorage.getItem('ticket4t_coupon')||'')}" maxlength="40"><button class="btn btn-outline btn-small" type="button" data-action="apply-coupon">Áp dụng</button></div><div id="coupon-feedback" class="coupon-feedback" aria-live="polite"></div><a class="text-link text-small" href="#/promotions" target="_blank" rel="noopener" style="margin-top:15px">Xem ưu đãi và điều kiện ${icon('arrow')}</a></section>`);restoreCheckoutAttempt(form);updateCheckoutTotals();updateHoldClocks();}
function pointOptions(points,selected){return (points||[]).map(p=>`<option value="${esc(fieldPoint(p))}" ${fieldPoint(p)===selected?'selected':''}>${esc(fieldPoint(p))}</option>`).join('');}
function updateCheckoutTotals(){const subtotal=draftSubtotal(),quote=v3.quote;document.querySelectorAll('[data-checkout-total]').forEach(el=>el.textContent=money(quote?.total??subtotal));const savings=document.getElementById('checkout-savings');if(savings)savings.innerHTML=quote&&quote.discount>0?`<div class="summary-line"><span>Giá trước ưu đãi</span><strong>${money(quote.subtotal)}</strong></div><div class="summary-line savings"><span>Ưu đãi ${esc(quote.couponCode)}</span><strong>−${money(quote.discount)}</strong></div>`:'';}
function updateHoldClocks(){const holds=activeHolds(),hasHolds=holds.length>0,expected=checkoutLegs().length?checkoutLegs():(v3.journey?.legs||[]),expired=expected.length>0&&expected.some(leg=>!holdAlive(leg.hold));const seconds=hasHolds?Math.max(0,Math.ceil(Math.min(...holds.map(h=>new Date(h.expiresAt).getTime()))/1000-Date.now()/1000)):0;document.querySelectorAll('[data-hold-clock]').forEach(el=>{el.textContent=expired?'Thời gian giữ chỗ đã hết. Kiểm tra lại trước khi đặt.':hasHolds?`Còn ${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')} để hoàn tất${holds.length>1?' cả hai chiều':''}.`:'';el.classList.toggle('hold-expired',expired);});const button=document.getElementById('book-button');if(button&&expected.length){button.disabled=(expired&&!replayableCheckout())||button.dataset.busy==='true';button.dataset.holdExpired=String(expired);}document.querySelectorAll('[data-action="renew-holds"]').forEach(el=>el.hidden=!expired||replayableCheckout());}
async function renewHolds(button){button.disabled=true;const legs=checkoutLegs(),created=[];try{await Promise.allSettled(legs.map(leg=>releaseHold(leg.hold)));legs.forEach(leg=>leg.hold=null);checkoutDraft.legs=legs;persistDraft();for(const leg of legs){const data=await api('/api/holds',{method:'POST',body:JSON.stringify({tripId:leg.tripId,seats:leg.seats})});created.push(data.hold);}legs.forEach((leg,i)=>leg.hold=created[i]);checkoutDraft.legs=legs;checkoutDraft.hold=created[0];persistDraft();if(v3.journey){v3.journey.legs=legs;persistJourney();}toast('Chỗ đã được giữ lại. Vui lòng hoàn tất trong thời gian hiển thị.');updateHoldClocks();}catch(e){await Promise.allSettled(created.map(releaseHold));toast(e.message,true);updateHoldClocks();}finally{button.disabled=false;}}
async function applyCoupon(button){
  const input=document.getElementById('coupon-code'),phoneInput=document.getElementById('phone'),feedback=document.getElementById('coupon-feedback');
  const code=input?.value.trim().toUpperCase(),phone=phoneInput?.value.trim(),version=state.routeVersion;
  if(!code){v3.quote=null;sessionStorage.removeItem('ticket4t_coupon');updateCheckoutTotals();feedback.className='coupon-feedback';feedback.textContent='Mã ưu đãi đã được xóa.';return;}
  if(!phone){feedback.textContent='Điền số điện thoại hành khách trước khi kiểm tra ưu đãi.';return;}
  const legs=checkoutLegs().map(leg=>({tripId:leg.tripId,seats:[...leg.seats],holdToken:leg.hold?.token}));
  const current=()=>version===state.routeVersion&&input.isConnected&&input.value.trim().toUpperCase()===code&&phoneInput.value.trim()===phone;
  button.disabled=true;
  try{
    const quote=await api('/api/promotions/quote',{method:'POST',body:JSON.stringify({legs,couponCode:code,phone})});
    if(!current())return;
    v3.quote={...quote,phone};sessionStorage.setItem('ticket4t_coupon',quote.couponCode);
    feedback.className='coupon-feedback coupon-success';feedback.textContent=`Đã áp dụng ${quote.couponCode} · Tiết kiệm ${money(quote.discount)}. Ưu đãi được xác nhận lại khi đặt.`;updateCheckoutTotals();
  }catch(e){if(!current())return;v3.quote=null;feedback.className='coupon-feedback coupon-error';feedback.textContent=e.message;updateCheckoutTotals();}
  finally{if(button.isConnected)button.disabled=false;}
}

function pendingOnlinePayment(b){return onlinePaymentMethods.includes(b?.paymentMethod)&&b.status==='pending_payment'&&b.paymentStatus==='pending';}
function stopBookingPolling(){if(bookingPolling?.timer)clearTimeout(bookingPolling.timer);bookingPolling=null;}
function startBookingPolling(booking){
  if(!pendingOnlinePayment(booking)){stopBookingPolling();return;}
  if(bookingPolling?.code===booking.code&&bookingPolling.version===state.routeVersion)return;
  stopBookingPolling();
  const poll=bookingPolling={code:booking.code,phone:booking.phone,version:state.routeVersion,until:Date.now()+60000,timer:null,busy:false};
  const tick=async()=>{if(bookingPolling!==poll||poll.version!==state.routeVersion)return;if(Date.now()>=poll.until){const note=document.getElementById('payment-status-note');if(note)note.textContent='Chưa có kết quả mới. Bạn có thể cập nhật trạng thái hoặc tiếp tục thanh toán trước thời hạn giữ chỗ.';return;}if(document.visibilityState!=='hidden')await refreshBooking(null,true);if(bookingPolling===poll)poll.timer=setTimeout(tick,5000);};
  poll.timer=setTimeout(tick,5000);
}
async function refreshBooking(button,quiet=false){
  const booking=state.lookup,version=state.routeVersion,poll=bookingPolling;
  if(!booking?.code||poll?.busy)return;
  if(poll)poll.busy=true;if(button)button.disabled=true;
  try{const data=await api(`/api/bookings/lookup?${qs({code:booking.code,phone:booking.phone})}`);if(version!==state.routeVersion||state.lookup?.code!==booking.code)return;const changed=JSON.stringify(data.booking)!==JSON.stringify(booking);state.lookup=data.booking;if(changed){renderReceipt(data.booking);attachReviewForm(data.booking);}if(!quiet)toast(changed?'Trạng thái đặt chỗ đã được cập nhật.':'Đã kiểm tra. Trạng thái đặt chỗ chưa thay đổi.');}
  catch(e){if(!quiet&&version===state.routeVersion)toast(e.message,true);}
  finally{if(poll)poll.busy=false;if(button?.isConnected)button.disabled=false;}
}
async function continuePayment(button){
  const booking=state.lookup,version=state.routeVersion;if(!pendingOnlinePayment(booking)||sourceDemo(booking)||button.disabled)return;button.disabled=true;
  try{const data=await api(`/api/bookings/${encodeURIComponent(booking.code)}/payment-link`,{method:'POST',body:JSON.stringify({phone:booking.phone})});if(version!==state.routeVersion||state.lookup?.code!==booking.code)return;state.lookup=data.booking;rememberPaymentBooking(data.booking);location.assign(paymentDestination(data.paymentUrl));}
  catch(e){if(version===state.routeVersion){toast(e.message,true);await refreshBooking(null,true);}}
  finally{if(button.isConnected)button.disabled=false;}
}

async function submitCheckout(form){
  if(form.querySelector('[type="submit"]')?.dataset.busy==='true')return;
  const request=checkoutRequest(form),{values,legs}=request,version=state.routeVersion,draft=checkoutDraft;
  if(!legs.length){toast('Hãy chọn lại chỗ cho hành trình.',true);return;}
  const replay=replayableCheckout(form);
  if(!replay){
    clearCheckoutAttempt();
    if(legs.some(leg=>!holdAlive(leg.hold))){formError('checkout-error','Thời gian giữ chỗ đã hết. Hãy kiểm tra và giữ lại chỗ trước khi đặt.');updateHoldClocks();return;}
    if(request.values.couponCode.trim()&&(!v3.quote||v3.quote.couponCode!==values.couponCode.trim().toUpperCase()||v3.quote.phone!==values.phone.trim())){formError('checkout-error','Vui lòng áp dụng lại mã ưu đãi để kiểm tra điều kiện với số điện thoại hiện tại.');return;}
    checkoutAttempt={key:typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(24)),value=>value.toString(16).padStart(2,'0')).join(''),path:request.path,body:request.body,createdAt:Date.now(),quote:v3.quote};persistCheckoutAttempt();
  }
  const attempt=checkoutAttempt;
  setBusy(form,true,replay?'Đang lấy lại kết quả đặt chỗ…':'Đang xác nhận chỗ và ưu đãi…');
  formError('checkout-error','');
  try{
    const data=await api(attempt.path,{method:'POST',headers:{'Idempotency-Key':attempt.key},body:attempt.body});
    clearCheckoutAttempt(attempt.key);
    if(checkoutDraft===draft){checkoutDraft=null;v3.journey=null;v3.quote=null;persistDraft();persistJourney();sessionStorage.removeItem('ticket4t_coupon');}
    if(data.booking)rememberPaymentBooking(data.booking);
    if(version!==state.routeVersion){toast(`Đã tạo ${data.order?'đơn':'đặt chỗ'} ${data.order?.code||data.booking?.code}. Bạn có thể tra cứu trong Vé của tôi.`);return;}
    if(data.booking)state.lookup=data.booking;
    if(data.paymentError)toast(data.paymentError.message||'Chưa tạo được liên kết thanh toán. Đặt chỗ đã được giữ; vui lòng kiểm tra lại trạng thái.',true);
    if(data.paymentUrl){location.assign(paymentDestination(data.paymentUrl));return;}
    if(data.order){v3.order=data.order;location.hash=`#/order/${encodeURIComponent(data.order.code)}?${qs({phone:values.phone.trim()})}`;}
    else location.hash=`#/booking/${encodeURIComponent(data.booking.code)}?${qs({phone:values.phone.trim()})}`;
  }catch(e){
    if(!e.ambiguous)clearCheckoutAttempt(attempt.key);
    if(version===state.routeVersion){formError('checkout-error',e.ambiguous?`${e.message} Giữ nguyên thông tin và xác nhận lại; hệ thống sẽ lấy kết quả của cùng yêu cầu, tránh tạo vé trùng.`:e.message);}
  }finally{if(form.isConnected)setBusy(form,false);updateHoldClocks();}
}

function renderReceipt(b){renderReceiptV2(b);const actions=document.querySelector('.receipt-actions');if(onlinePaymentMethods.includes(b.paymentMethod)){rememberPaymentBooking(b);actions?.insertAdjacentHTML('afterbegin',`${pendingOnlinePayment(b)&&!sourceDemo(b)&&new Date(b.expiresAt).getTime()>Date.now()?'<button class="btn" data-action="continue-payment">'+icon('qr')+'Tiếp tục thanh toán</button>':''}<button class="btn btn-outline" data-action="refresh-booking">${icon('refresh')}Cập nhật trạng thái</button>`);document.querySelector('.receipt-notice')?.insertAdjacentHTML('afterend',`<p class="muted text-small" id="payment-status-note" aria-live="polite">${pendingOnlinePayment(b)?'Đang kiểm tra xác nhận thanh toán từ cổng thanh toán…':''}</p>`);}startBookingPolling(b);if(['reserved','confirmed'].includes(b.status)&&['pending','paid'].includes(b.paymentStatus)&&new Date(`${b.trip?.date}T${b.trip?.departureTime}:00+07:00`).getTime()>Date.now()+2*3600000)actions?.insertAdjacentHTML('beforeend',`<a class="btn btn-outline" href="#/reschedule/${encodeURIComponent(b.code)}?${qs({phone:b.phone})}">${icon('refresh')}Đổi chuyến</a>`);if(b.discount>0)document.querySelector('.receipt-aside .summary-total')?.insertAdjacentHTML('beforebegin',`<div class="summary-line"><span>Giá trước ưu đãi</span><strong>${money(b.subtotal||b.total+b.discount)}</strong></div><div class="summary-line savings"><span>Mã ${esc(b.couponCode||'ưu đãi')}</span><strong>−${money(b.discount)}</strong></div>`);if(b.isDemo||b.note)document.querySelector('.receipt-notice span')?.insertAdjacentHTML('beforeend',`<br><strong>${esc(b.note||'Chứng từ và trạng thái thanh toán là dữ liệu kiểm thử; không có giao dịch tiền thật.')}</strong>`);}
async function orderPage(code,version){shell(`<div class="container page-main">${loading('Đang tải hành trình khứ hồi…')}</div>`,'Đơn khứ hồi');try{const data=await api(`/api/orders/lookup?${qs({code,phone:queryValues().phone||v3.order?.phone||''})}`);if(version!==state.routeVersion)return;v3.order=data.order;renderOrder(data.order);}catch(e){if(version===state.routeVersion)shell(errorPage(e.message),'Đơn khứ hồi');}}
function renderOrder(order){const bookings=order.bookings||[],demo=bookings.some(sourceDemo);shell(`<div class="container page-main"><div class="receipt-wrap">${breadcrumb('Đơn khứ hồi')}<div class="receipt-header"><div class="receipt-icon">${icon('swap')}</div><h1>Hai chiều, một hành trình</h1><p>${demo?'Đơn khứ hồi minh họa. Không dùng để lên xe.':'Tra cứu và quản lý từng chiều của hành trình dưới đây.'}</p></div><section class="card pad"><div class="flex between wrap"><div><div class="eyebrow">Mã đơn khứ hồi</div><div class="receipt-code" style="margin-bottom:10px">${esc(order.code)}</div></div><span class="badge ${demo?'badge-warm':''}">${demo?'Dữ liệu minh họa':'Khứ hồi'}</span></div>${bookings.map((booking,i)=>`<article class="order-booking"><div class="flex between wrap"><span class="badge badge-gray">${i?'Chiều về':'Chiều đi'} · ${esc(booking.code)}</span>${statusBadge(booking)}</div><h3>${esc(booking.trip?.fromName)} → ${esc(booking.trip?.toName)}</h3><p>${esc(booking.trip?.operatorName)} · ${dateLabel(booking.trip?.date,true)} · ${esc(booking.trip?.departureTime)}<br>Chỗ ${(booking.seats||[]).map(esc).join(', ')} · ${money(booking.total)}</p><a class="btn btn-outline btn-small" href="#/booking/${encodeURIComponent(booking.code)}?${qs({phone:booking.phone||order.phone})}">Chi tiết / hủy / đổi chiều này ${icon('arrow')}</a></article>`).join('')}<div class="summary-line"><span>Giá trước ưu đãi</span><strong>${money(order.subtotal??order.total)}</strong></div>${order.discount>0?`<div class="summary-line savings"><span>Ưu đãi ${esc(order.couponCode)}</span><strong>−${money(order.discount)}</strong></div>`:''}<div class="summary-total"><span>Tổng tiền đơn</span><strong>${money(order.total)}</strong></div>${order.activeTotal!==undefined&&Number(order.activeTotal)!==Number(order.total)?`<div class="summary-line"><span>Các chiều còn hiệu lực</span><strong>${money(order.activeTotal)}</strong></div>`:''}<div class="notice">${icon('info')}<span>Mỗi chiều có mã đặt chỗ và trạng thái riêng. Hủy hoặc đổi một chiều không tự thay đổi chiều còn lại. ${demo?'Mọi dữ liệu và giao dịch hiển thị ở đây là minh họa.':'Thanh toán tại nhà xe theo xác nhận của từng chiều.'}</span></div></section><div class="receipt-actions"><button class="btn" data-action="print">${icon('print')}In / lưu PDF</button><a class="btn btn-outline" href="#/tickets">Vé của tôi</a></div></div></div>`,'Đơn '+order.code);}
async function ticketsPage(version){
  const q=queryValues(),code=(q.code||'').trim().toUpperCase(),contact=paymentContact(code);
  if(contact&&(location.hash||'').startsWith('#/lookup')){try{const data=await api(`/api/bookings/lookup?${qs({code,phone:contact})}`);if(version!==state.routeVersion)return;state.lookup=data.booking;location.replace(`#/booking/${encodeURIComponent(data.booking.code)}`);return;}catch{if(version!==state.routeVersion)return;}}
  await ticketsPageV2(version);if(version!==state.routeVersion)return;if(contact){const input=document.getElementById('lookup-phone');if(input)input.value=contact;}
  document.querySelector('.lookup-form>p')?.replaceChildren(document.createTextNode('Nhập mã đặt chỗ hoặc mã đơn khứ hồi và số điện thoại của bạn.'));if(!state.user)return;try{const data=await api('/api/orders');if(version!==state.routeVersion||!data.orders?.length)return;document.getElementById('booking-history')?.insertAdjacentHTML('afterbegin',`<div class="history-list order-history">${data.orders.map(order=>`<article class="card history-card"><div><span class="badge">Khứ hồi · ${esc(order.code)}</span><h3>${esc(order.bookings?.[0]?.trip?.fromName)} ⇄ ${esc(order.bookings?.[0]?.trip?.toName)}</h3><p>${dateTimeLabel(order.createdAt)} · ${money(order.total)} · ${order.bookings?.length||0} chiều</p></div><a class="btn btn-outline btn-small" href="#/order/${encodeURIComponent(order.code)}?${qs({phone:order.phone})}">Xem đơn ${icon('arrow')}</a></article>`).join('')}</div>`);}catch{}}

function promoValue(p){return p.type==='percentage'?`${Number(p.value)}%`:money(p.value);}
function promoCard(p){return `<article class="card promotion-card"><div class="promotion-icon">${icon('ticket')}</div><div class="flex between"><span class="eyebrow">${p.roundTripOnly?'Dành cho khứ hồi':'Ưu đãi hành trình'}</span>${sourceDemo(p)?'<span class="badge badge-warm">Minh họa</span>':''}</div><h3>${esc(p.title)}</h3><p>${esc(p.description||`Giảm ${promoValue(p)} theo điều kiện áp dụng.`)}</p><div class="promo-code"><strong>${esc(p.code)}</strong><button class="text-link" data-action="use-promo" data-code="${esc(p.code)}">Chọn mã ${icon('arrow')}</button></div><details><summary>Điều kiện áp dụng</summary><ul><li>Ưu đãi ${promoValue(p)}${p.maxDiscount?`, tối đa ${money(p.maxDiscount)}`:''}.</li><li>Tổng tiền tối thiểu ${money(p.minSpend||0)}.</li>${p.operatorIds?.length?'<li>Áp dụng cho các nhà xe được chỉ định.</li>':''}${p.routeIds?.length?'<li>Áp dụng cho các tuyến được chỉ định.</li>':''}<li>${p.roundTripOnly?'Chỉ dành cho đơn khứ hồi.':'Áp dụng theo điều kiện chuyến được chọn.'}</li><li>${p.perCustomer?`Tối đa ${Number(p.perCustomer)} lần mỗi khách.`:'Theo hạn mức còn lại.'}</li><li>${p.expiresAt?`Hiệu lực đến ${dateTimeLabel(p.expiresAt)}.`:'Thời gian áp dụng được kiểm tra khi đặt.'}</li></ul></details></article>`;}
async function loadPromotions(elementId,limit=100){const version=state.routeVersion;try{const data=await api('/api/promotions');if(version!==state.routeVersion)return;v3.promotions=data.promotions||[];const el=document.getElementById(elementId);if(el)el.innerHTML=v3.promotions.length?v3.promotions.slice(0,limit).map(promoCard).join(''):`<div class="card empty"><h3>Ưu đãi đang được chuẩn bị</h3><p>Chưa có mã đang mở. Bạn vẫn có thể chọn hành trình với giá hiển thị rõ ràng.</p></div>`;}catch(e){const el=document.getElementById(elementId);if(el&&version===state.routeVersion)el.innerHTML=`<div class="notice notice-warm">${icon('info')}${esc(e.message)}</div>`;}}
function promotionsPage(){shell(`<div class="container page-main">${breadcrumb('Ưu đãi')}<div class="page-heading"><div class="eyebrow">Đi xa hơn, chọn dễ hơn</div><h1>Ưu đãi cho hành trình của bạn</h1><p>Mã được kiểm tra theo chuyến, tổng tiền và số lần sử dụng. Ưu đãi minh họa luôn được gắn nhãn.</p></div><div class="promotion-grid" id="promotions-list">${loading('Đang tải ưu đãi…')}</div></div>`,'Ưu đãi');loadPromotions('promotions-list');}
function favoritesPage(){shell(`<div class="container page-main">${breadcrumb('Chuyến đã lưu')}<div class="page-heading"><div class="eyebrow">Những hành trình bạn để dành</div><h1>Chuyến xe đã lưu</h1><p>Lưu trên trình duyệt này. Giá và chỗ trống được kiểm tra lại khi mở chuyến.</p></div><div class="trip-list">${v3.favorites.length?v3.favorites.map(tripCard).join(''):`<div class="card empty"><div class="empty-icon">${icon('heart')}</div><h3>Chọn một chuyến để lưu</h3><p>Nhấn “Lưu chuyến” trong kết quả tìm kiếm để dễ tìm lại.</p><a class="btn" href="${routeHref('ho-chi-minh','da-lat')}">Tìm chuyến xe</a></div>`}</div></div>`,'Chuyến đã lưu');}
function comparePage(){const trips=v3.compare;shell(`<div class="container page-main">${breadcrumb('So sánh chuyến xe')}<div class="page-heading"><div class="eyebrow">Một lựa chọn vừa ý</div><h1>So sánh hành trình</h1><p>Chọn từ 2 đến 3 chuyến trong kết quả tìm kiếm. Giá và chỗ trống sẽ được kiểm tra lại trước khi đặt.</p></div>${trips.length>=2?`<div class="compare-grid">${trips.map(t=>`<article class="card compare-card"><img src="${esc(imagePath(t.image))}" alt="Xe ${esc(t.operatorName)}"><div class="pad"><div class="flex between"><h3>${esc(t.operatorName)}</h3><button class="trip-tool" data-action="remove-compare" data-trip-id="${esc(t.id)}" aria-label="Bỏ so sánh ${esc(t.operatorName)}">${icon('close')}</button></div><p>${esc(t.fromName)} → ${esc(t.toName)}</p><dl><div><dt>Giá từ</dt><dd>${money(t.price)}</dd></div><div><dt>Ngày đi</dt><dd>${dateLabel(t.date,true)}</dd></div><div><dt>Khởi hành</dt><dd>${esc(t.departureTime)}</dd></div><div><dt>Đến dự kiến</dt><dd>${esc(t.arrivalTime)}</dd></div><div><dt>Thời gian</dt><dd>${duration(t.durationMinutes)}</dd></div><div><dt>Loại xe</dt><dd>${esc(t.typeName||t.type)}</dd></div><div><dt>Tiện ích</dt><dd>${(t.amenities||[]).map(esc).join(' · ')||'Xem thông tin chuyến'}</dd></div></dl>${sourceDemo(t)?'<span class="badge badge-warm">Dữ liệu minh họa</span>':''}<a class="btn btn-block" href="${tripContextHref(t)}" style="margin-top:20px">Xem chỗ trống ${icon('arrow')}</a></div></article>`).join('')}</div>`:`<div class="card empty"><div class="empty-icon">${icon('swap')}</div><h3>Thêm ${2-trips.length} chuyến để so sánh</h3><p>Nhấn “Thêm so sánh” ở chuyến bạn quan tâm. Bạn có thể so sánh tối đa 3 chuyến.</p><a class="btn" href="${routeHref('ho-chi-minh','da-lat')}">Tìm chuyến xe</a></div>`}</div>`,'So sánh chuyến');}

async function reschedulePage(code,version){const q=queryValues();shell(`<div class="container page-main">${loading('Đang kiểm tra điều kiện đổi chuyến…')}</div>`,'Đổi chuyến');try{const data=await api(`/api/bookings/lookup?${qs({code,phone:q.phone||v3.reschedule?.booking?.phone})}`);if(version!==state.routeVersion)return;v3.reschedule={booking:data.booking};sessionStorage.setItem('ticket4t_reschedule',JSON.stringify(v3.reschedule));const b=data.booking,t=b.trip;if(q.confirm==='1'&&checkoutDraft?.mode==='reschedule'){renderRescheduleConfirmation(b);return;}const date=q.date||t.date;const results=await api(`/api/trips?${qs({from:t.from,to:t.to,date,operator:t.operatorId,limit:30})}`);if(version!==state.routeVersion)return;shell(`<div class="container page-main">${breadcrumb('Đổi chuyến')}<div class="page-heading"><div class="eyebrow">Điều chỉnh hành trình</div><h1>Đổi chuyến cho ${esc(code)}</h1><p>${esc(t.fromName)} → ${esc(t.toName)} · ${esc(t.operatorName)} · Chuyến hiện tại ${dateLabel(t.date)} ${esc(t.departureTime)}</p></div><div class="notice">${icon('info')}<span>Đổi trước giờ khởi hành ít nhất 2 giờ, sang chuyến cùng nhà xe, tuyến, số hành khách và giá gốc. Chuyến minh họa chỉ đổi sang chuyến minh họa; chuyến thực tế chỉ đổi sang chuyến thực tế. Ưu đãi đã áp dụng được giữ. Nếu có chênh lệch, vui lòng liên hệ nhà xe. Hệ thống kiểm tra lại khi xác nhận.</span></div><form class="card pad reschedule-search" id="reschedule-search-form" data-code="${esc(code)}" data-phone="${esc(b.phone)}"><div class="form-field"><label for="reschedule-date">Ngày muốn đổi</label><input type="date" id="reschedule-date" name="date" value="${esc(date)}" min="${today()}" required></div><button class="btn" type="submit">Tìm chuyến thay thế ${icon('search')}</button><a class="text-link" href="#/booking/${encodeURIComponent(code)}?${qs({phone:b.phone})}">Quay lại đặt chỗ</a></form><div class="trip-list">${results.trips.filter(trip=>trip.id!==t.id).map(tripCard).join('')||'<div class="card empty"><h3>Chưa có chuyến thay thế trong ngày này</h3><p>Hãy đổi ngày để xem thêm lựa chọn của cùng nhà xe.</p></div>'}</div></div>`,'Đổi chuyến');}catch(e){if(version===state.routeVersion)shell(errorPage(e.message),'Đổi chuyến');}}
function renderRescheduleConfirmation(b){const leg=checkoutLegs()[0],t=leg.trip,targetNet=Math.max(1,legSubtotal(leg)-Number(b.discount||0));state.trip=t;state.selected=leg.seats;shell(`<div class="container page-main"><div class="receipt-wrap">${breadcrumb('Xác nhận đổi chuyến')}<div class="page-heading"><h1>Kiểm tra chuyến mới</h1><p>Mã đặt chỗ ${esc(b.code)} sẽ được cập nhật sau khi đổi thành công.</p></div><form class="card pad form-section" id="reschedule-confirm-form" data-code="${esc(b.code)}" data-phone="${esc(b.phone)}"><div class="hold-banner">${icon('clock')}<span data-hold-clock></span></div><div id="reschedule-error" class="form-error" role="alert"></div><div class="reschedule-comparison"><div><span class="badge badge-gray">Chuyến hiện tại</span><h3>${dateLabel(b.trip.date,true)} · ${esc(b.trip.departureTime)}</h3><p>Chỗ ${(b.seats||[]).map(esc).join(', ')}<br>Tổng sau ưu đãi ${money(b.total)}<br><small>Giá gốc ${money(b.subtotal??b.total)}</small></p></div>${icon('arrow')}<div><span class="badge">Chuyến mới</span><h3>${dateLabel(t.date,true)} · ${esc(t.departureTime)}</h3><p>Chỗ ${leg.seats.map(esc).join(', ')}<br>Tổng sau ưu đãi ${money(targetNet)}<br><small>Giá gốc ${money(legSubtotal(leg))}</small></p></div></div><p>${b.discount>0?'Giữ mã '+esc(b.couponCode||'ưu đãi')+' · Giảm '+money(b.discount)+'. ':''}Tổng đặt chỗ sau khi đổi: ${money(targetNet)}. Chuyến mới phải có cùng giá gốc.</p><p>${esc(t.operatorName)} · ${esc(t.fromName)} → ${esc(t.toName)}</p><div class="form-grid"><div class="form-field"><label for="change-pickup">Điểm đón mới</label><select id="change-pickup" name="pickup" required>${pointOptions(t.pickupPoints)}</select></div><div class="form-field"><label for="change-dropoff">Điểm trả mới</label><select id="change-dropoff" name="dropoff" required>${pointOptions(t.dropoffPoints)}</select></div></div><label class="consent"><input type="checkbox" required><span>Tôi đã kiểm tra ngày, giờ, chỗ và điểm đón của chuyến mới.</span></label><div class="flex wrap" style="margin-top:23px"><button class="btn" id="book-button" type="submit">Xác nhận đổi chuyến ${icon('refresh')}</button><a class="btn btn-outline" href="#/booking/${encodeURIComponent(b.code)}?${qs({phone:b.phone})}">Giữ chuyến cũ</a></div></form></div></div>`,'Xác nhận đổi chuyến');updateHoldClocks();}
async function submitReschedule(form){const leg=checkoutLegs()[0];if(!leg||!holdAlive(leg.hold)){formError('reschedule-error','Chỗ chuyến mới đã hết thời gian giữ. Hãy quay lại chọn chỗ.');return;}const values=Object.fromEntries(new FormData(form));setBusy(form,true,'Đang xác nhận đổi chuyến…');try{const data=await api(`/api/bookings/${encodeURIComponent(form.dataset.code)}/reschedule`,{method:'POST',body:JSON.stringify({tripId:leg.tripId,seats:leg.seats,pickup:values.pickup,dropoff:values.dropoff,phone:form.dataset.phone,holdToken:leg.hold.token})});state.lookup=data.booking;checkoutDraft=null;persistDraft();v3.reschedule=null;sessionStorage.removeItem('ticket4t_reschedule');toast('Đặt chỗ đã được đổi sang chuyến mới.');location.hash=`#/booking/${encodeURIComponent(data.booking.code)}?${qs({phone:data.booking.phone})}`;}catch(e){formError('reschedule-error',e.message);}finally{setBusy(form,false);updateHoldClocks();}}

document.addEventListener('submit',async event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;
  if(form.id==='search-form'){event.preventDefault();event.stopImmediatePropagation();const values=Object.fromEntries(new FormData(form));if(values.from===values.to){toast('Điểm đến cần khác nơi xuất phát.',true);return;}if(values.date<today()||(values.tripMode==='roundtrip'&&readSearch().leg!=='return'&&values.returnDate<values.date)){toast('Kiểm tra ngày đi và ngày về của hành trình.',true);return;}setBusy(form,true,'Đang tìm chuyến…');const mode=values.tripMode,current=readSearch(),outbound=v3.journey?.legs[0];delete values.tripMode;if(current.leg==='return'&&mode==='roundtrip'&&outbound&&values.from===outbound.trip.to&&values.to===outbound.trip.from){if(values.date<(outbound.trip.arrivalDate||outbound.trip.date)){toast('Ngày về cần từ ngày chiều đi đến nơi trở đi.',true);setBusy(form,false);return;}await Promise.allSettled((v3.journey.legs.slice(1)||[]).map(leg=>releaseHold(leg.hold)));v3.journey.legs=[outbound];v3.journey.returnDate=values.date;checkoutDraft=null;persistDraft();persistJourney();navigateSearch({...values,mode,returnDate:values.date,leg:'return'},form);}else{await resetJourney();navigateSearch({...values,mode,leg:'outbound'},form);}return;}
  if(form.id==='checkout-form'&&checkoutLegs().length){event.preventDefault();event.stopImmediatePropagation();await submitCheckout(form);return;}
  if(form.id==='lookup-form'){event.preventDefault();event.stopImmediatePropagation();const values=Object.fromEntries(new FormData(form)),code=values.code.trim().toUpperCase(),phone=values.phone.trim(),version=state.routeVersion;setBusy(form,true,'Đang tra cứu…');try{let data;try{data=await api(`/api/bookings/lookup?${qs({code,phone})}`);}catch(e){if(e.status!==404)throw e;data=await api(`/api/orders/lookup?${qs({code,phone})}`);}if(version!==state.routeVersion)return;if(data.order){v3.order=data.order;location.hash=`#/order/${encodeURIComponent(data.order.code)}?${qs({phone})}`;}else{state.lookup=data.booking;location.hash=`#/booking/${encodeURIComponent(data.booking.code)}?${qs({phone})}`;}}catch(e){if(version===state.routeVersion)formError('lookup-error',e.message);}finally{setBusy(form,false);}return;}
  if(form.id==='reschedule-search-form'){event.preventDefault();event.stopImmediatePropagation();location.hash=`#/reschedule/${encodeURIComponent(form.dataset.code)}?${qs({phone:form.dataset.phone,date:new FormData(form).get('date')})}`;}
  if(form.id==='reschedule-confirm-form'){event.preventDefault();event.stopImmediatePropagation();await submitReschedule(form);}
},true);
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;if(!['checkout','favorite','compare','remove-compare','apply-coupon','use-promo','renew-holds','clear-filters','restart-outbound','continue-payment','refresh-booking'].includes(action))return;event.preventDefault();event.stopImmediatePropagation();if(action==='continue-payment'){await continuePayment(button);return;}if(action==='refresh-booking'){await refreshBooking(button);return;}if(action==='restart-outbound'){const outward=v3.journey?.legs[0]||checkoutLegs()[0],returnDate=v3.journey?.returnDate||checkoutLegs()[1]?.trip.date;if(!outward){location.hash='#/';return;}await resetJourney();location.hash=`#/search?${qs({from:outward.trip.from,to:outward.trip.to,date:outward.trip.date,mode:'roundtrip',returnDate,leg:'outbound'})}`;return;}if(action==='clear-filters'){updateSearch({type:'',operator:'',minPrice:'',maxPrice:'',time:'',pickup:'',dropoff:'',q:'',page:1});return;}if(action==='checkout'){await continueJourney(button);return;}if(action==='renew-holds'){await renewHolds(button);return;}if(action==='apply-coupon'){await applyCoupon(button);return;}if(action==='use-promo'){sessionStorage.setItem('ticket4t_coupon',button.dataset.code);toast(`Đã chọn mã ${button.dataset.code}. Kiểm tra điều kiện tại bước đặt vé.`);location.hash=checkoutLegs().length?'#/checkout':routeHref('ho-chi-minh','da-lat');return;}
  const id=button.dataset.tripId,trip=v3.trips.get(String(id))||v3.favorites.find(t=>String(t.id)===String(id))||v3.compare.find(t=>String(t.id)===String(id));
  if(action==='favorite'&&trip){const exists=v3.favorites.some(t=>String(t.id)===String(id));v3.favorites=exists?v3.favorites.filter(t=>String(t.id)!==String(id)):[trip,...v3.favorites].slice(0,50);localStorage.setItem('ticket4t_favorites',JSON.stringify(v3.favorites));document.querySelectorAll(`[data-action="favorite"][data-trip-id="${CSS.escape(id)}"]`).forEach(el=>{el.classList.toggle('is-saved',!exists);el.setAttribute('aria-pressed',!exists);el.innerHTML=icon('heart')+(!exists?'Đã lưu':'Lưu chuyến');});const savedShortcut=document.getElementById('favorites-shortcut');if(savedShortcut)savedShortcut.innerHTML=icon('heart')+`Đã lưu (${v3.favorites.length})`;toast(exists?'Đã bỏ chuyến khỏi danh sách lưu.':'Chuyến đã được lưu trên trình duyệt này.');if(location.hash==='#/favorites')favoritesPage();}
  if((action==='compare'||action==='remove-compare')&&trip){const exists=v3.compare.some(t=>String(t.id)===String(id));if(!exists&&v3.compare.length>=3){toast('Bạn có thể so sánh tối đa 3 chuyến. Bỏ một chuyến trước khi thêm.',true);return;}v3.compare=exists?v3.compare.filter(t=>String(t.id)!==String(id)):[...v3.compare,trip];localStorage.setItem('ticket4t_compare',JSON.stringify(v3.compare));document.querySelectorAll(`[data-action="compare"][data-trip-id="${CSS.escape(id)}"]`).forEach(el=>{el.classList.toggle('is-saved',!exists);el.setAttribute('aria-pressed',!exists);el.innerHTML=icon('swap')+(!exists?'Đã chọn so sánh':'Thêm so sánh');});const shortcut=document.getElementById('compare-shortcut');if(shortcut)shortcut.innerHTML=`So sánh (${v3.compare.length}/3) ${icon('swap')}`;if(location.hash==='#/compare')comparePage();else toast(`Đã chọn ${v3.compare.length}/3 chuyến để so sánh.`);}
},true);
document.addEventListener('change',event=>{if(event.target.name==='tripMode'){const form=event.target.closest('form'),roundtrip=event.target.value==='roundtrip';form.classList.toggle('roundtrip-search',roundtrip);const field=form.querySelector('.return-field');field.hidden=!roundtrip;field.querySelector('input').disabled=!roundtrip;}if(event.target.id==='search-date'){const input=document.getElementById('search-return-date');if(input){input.min=event.target.value;if(input.value<input.min)input.value=input.min;}}});
document.addEventListener('input',event=>{if(event.target.closest('#checkout-form'))updateHoldClocks();if(['coupon-code','phone'].includes(event.target.id)&&v3.quote){v3.quote=null;updateCheckoutTotals();const feedback=document.getElementById('coupon-feedback');if(feedback){feedback.className='coupon-feedback';feedback.textContent='Thông tin vừa thay đổi. Vui lòng áp dụng lại mã ưu đãi.';}}});
async function pollSeats(manual=false){
  if(v3.polling||document.visibilityState==='hidden'||!(location.hash||'').startsWith('#/trip/')||!state.trip)return;
  v3.polling=true;const id=state.trip.id,version=state.routeVersion;
  try{
    const data=await api(`/api/trips/${encodeURIComponent(id)}`);if(version!==state.routeVersion||state.trip?.id!==id)return;
    const fresh=data.trip||data,before=state.selected.length;state.trip=fresh;state.selected=state.selected.filter(label=>fresh.bookingOpen!==false&&fresh.seats.some(seat=>seat.label===label&&isSelectable(seat)));
    if(state.seatTab==='seats')for(const seat of fresh.seats){const button=document.querySelector(`[data-action="seat"][data-label="${CSS.escape(seat.label)}"]`);if(!button)continue;button.className=`seat ${seat.status}${state.selected.includes(seat.label)?' selected':''}`;button.disabled=!isSelectable(seat)||fresh.bookingOpen===false;button.setAttribute('aria-pressed',String(state.selected.includes(seat.label)));button.setAttribute('aria-label',`Chỗ ${seat.label}, ${money(seat.price)}, ${isSelectable(seat)?'còn trống':seat.status==='held'?'đang giữ':'đã đặt'}`);button.title=money(seat.price);}
    const summary=document.getElementById('seat-summary'),focused=summary?.contains(document.activeElement)?document.activeElement.dataset.action:null;
    if(summary){summary.innerHTML=seatSummary();if(focused)summary.querySelector(`[data-action="${CSS.escape(focused)}"]`)?.focus({preventScroll:true});}
    if(before!==state.selected.length)toast('Chỗ vừa thay đổi. Một số lựa chọn đã được cập nhật.',true);else if(manual)toast('Chỗ trống đã được cập nhật.');
  }catch(e){if(manual&&version===state.routeVersion)toast(e.message,true);}finally{v3.polling=false;}
}

async function route(){stopBookingPolling();const path=(location.hash||'#/').slice(1).split('?')[0];if(['/promotions','/favorites','/compare'].includes(path)||path.startsWith('/order/')||path.startsWith('/reschedule/')){const version=++state.routeVersion;window.scrollTo({top:0});if(!state.bootstrap){shell(errorPage('Chưa tải được dữ liệu hệ thống.'));return;}if(path==='/promotions')promotionsPage();else if(path==='/favorites')favoritesPage();else if(path==='/compare')comparePage();else if(path.startsWith('/order/'))await orderPage(decodeURIComponent(path.split('/')[2]),version);else await reschedulePage(decodeURIComponent(path.split('/')[2]),version);return;}await routeV2();}
setInterval(updateHoldClocks,1000);
setInterval(pollSeats,15000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){pollSeats();if(bookingPolling&&Date.now()<bookingPolling.until)refreshBooking(null,true);}});
init();

